import net.runelite.client.util.ImageUtil;

/** Lifecycle owns feature subscriptions and the single worker. Game reads stay on ClientThread. */
@Slf4j
@PluginDescriptor(name = "Ironclad Events", description = "Ironclad clan events on ironcladrs.com", tags = {"clan", "events", "ironclad"})
public class IroncladEventsPlugin extends Plugin
{
    @Inject private IroncladEventsConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ClientToolbar toolbar;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private ItemManager items;
    @Inject private PlayerGuard guard;
    @Inject private ApiClient api;
    @Inject private SyncService sync;
    @Inject private Outbox outbox;
    @Inject private WorkExecutor work;
    @Inject private Screenshots screenshots;
    @Inject private LootCollector loot;
    @Inject private BankAttestor bank;
    @Inject private PrecheckCapture pictures;
    @Inject private XpCollector xp;
    @Inject private KillCountCollector kc;
    @Inject private ProgressBatcher progress;
    @Inject private CollectionLogReader collection;
    @Inject private NewItemListener newItems;
    @Inject private AccountSnapshot account;
    @Inject private PersonalBestListener pbs;
    @Inject private ClanChatRelay chat;
    @Inject private DeathListener deaths;
    @Inject private ActivityCollector activity;
    @Inject private AccountLinker linker;
    private final List<Object> subscriptions = new ArrayList<>();
    private ScheduledFuture<?> ticker;
    private volatile boolean running;
    private IroncladPanel panel;
    private NavigationButton navigation;
    private boolean navigationVisible;
    private int shownOutbox = -1;
    private long activeGeneration = -1;

    @Override protected void startUp()
    {
        running = true; guard.activate(); work.start();
        register(loot);
        register(bank);
        register(xp);
        register(progress);
        register(collection);
        register(newItems);
        register(account);
        register(pbs);
        register(chat);
        register(deaths);
        register(activity);
        sync.listen(state -> publish(state));
        outbox.listen(message -> {
            int count = outbox.size();
            SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.status(message, count); } });
        });
        bank.listen(cards -> SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.bank(cards); } }));
        linker.listen(link -> SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.link(link); } }));
        SwingUtilities.invokeLater(() -> {
            if (!running) { return; }
            panel = new IroncladPanel(config, items, actions(guard.generation())); panel.link(linker.state());
            navigation = button(ImageUtil.loadImageResource(getClass(), "panel_icon.png"));
            visibility();
            // Obor's club as the sidebar icon (user, 2026-11-27: "i would prefer obors club"), drawn by
            // RuneLite from the game's own item picture; the helm shows until it has loaded.
            AsyncBufferedImage club = items.getImage(ItemID.HILLGIANT_BOSS_CLUB);
            club.onLoaded(() -> SwingUtilities.invokeLater(() -> useIcon(SidebarIcon.fit(club, 16))));
        });
        ticker = work.repeat(() -> clientThread.invoke(() -> { if (running) { pulse(); } }));
        log.info("Ironclad Events started");
    }
    private void register(Object feature) { eventBus.register(feature); subscriptions.add(feature); }
    private void pulse()
    {
        guard.refresh();
        if (activeGeneration != guard.generation()) { resetSession(); }
        Instant now = Instant.now(); sync.tick(now);
        outbox.pump(now); progress.tick(now); account.tick(now); chat.tick(now); activity.tick(now);
        if (shownOutbox != outbox.size())
        { shownOutbox = outbox.size(); int count = shownOutbox; SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.unsent(count); } }); }
    }
    private void resetSession()
    {
        activeGeneration = guard.generation();
        api.cancelAll(); outbox.clear(); bank.reset(); xp.reset(); kc.reset(); progress.reset();
        collection.reset(); newItems.reset(); account.reset(); pbs.reset(); chat.reset(); deaths.reset(); activity.reset(); screenshots.reset(); sync.reset();
    }
    private void publish(SessionState state)
    {
        int count = outbox.size(); long generation = guard.generation();
        SwingUtilities.invokeLater(() -> { if (running && panel != null) { panel.update(state, count, actions(generation)); } });
    }
    @Override protected void shutDown()
    {
        running = false;
        PlayerGuard.Identity old = guard.identity(); guard.deactivate();
        if (ticker != null) { ticker.cancel(false); ticker = null; }
        linker.cancel(); linker.listen(ignored -> {});
        subscriptions.forEach(eventBus::unregister); subscriptions.clear(); work.stop();
        clientThread.invoke(() -> {
            api.cancelAll(); resetSession();
            if (old != null) { api.request(old, "DELETE", "/session", null, null, null, ignored -> {}); }
        });
        SwingUtilities.invokeLater(() -> {
            if (panel != null) { panel.stop(); }
            if (navigation != null) { toolbar.removeNavigation(navigation); }
            navigationVisible = false; navigation = null; panel = null;
        });
    }
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (!IroncladEventsConfig.GROUP.equals(event.getGroup()) || !running) { return; }
        SwingUtilities.invokeLater(() -> { if (running) { visibility(); if (panel != null) { panel.render(); } } });
        if (Arrays.asList("showPanel", "chatNotices", "desktopNotices").contains(event.getKey())) { return; }
        // Linking only runs while Connect is on; switching it off stops a link in progress.
        if ("connect".equals(event.getKey()) && !config.connect()) { linker.cancel(); }
        clientThread.invoke(() -> {
            if (!running) { return; }
            PlayerGuard.Identity old = guard.identity(); api.cancelAll(); guard.clear(); guard.refresh(); resetSession();
            if (old != null && !config.connect()) { api.request(old, "DELETE", "/session", null, null, null, ignored -> {}); }
            pulse();
        });
    }
    private NavigationButton button(BufferedImage icon)
    { return NavigationButton.builder().tooltip("Ironclad Events").priority(5).icon(icon).panel(panel).build(); }
    private void useIcon(BufferedImage icon)
    {
        if (!running || navigation == null || icon == null) { return; }
        boolean shown = navigationVisible;
        if (shown) { toolbar.removeNavigation(navigation); navigationVisible = false; }
        navigation = button(icon);
        visibility();
    }
    private void visibility()
    {
        if (navigation == null) { return; }
        if (config.showPanel() && !navigationVisible) { toolbar.addNavigation(navigation); navigationVisible = true; }
        else if (!config.showPanel() && navigationVisible) { toolbar.removeNavigation(navigation); navigationVisible = false; }
    }
    private void dispatch(long generation, Runnable task)
    { clientThread.invoke(() -> { if (running && generation == guard.generation()) { task.run(); } }); }
    private IroncladPanel.Actions actions(long generation)
    {
        return new IroncladPanel.Actions()
        {
            @Override public void clanSettings(boolean enabled)
            { dispatch(generation, () -> configManager.setConfiguration(IroncladEventsConfig.GROUP, "useClanSettings", enabled)); }
            @Override public void clanDefaults(List<String> keys)
            {
                // Only our own upload keys, only ever switched on; the member confirmed this exact list in the panel.
                List<String> allowed = new ArrayList<>(keys); allowed.retainAll(Arrays.asList(IroncladEventsConfig.UPLOAD_KEYS));
                dispatch(generation, () -> {
                    for (String key : allowed) { configManager.setConfiguration(IroncladEventsConfig.GROUP, key, true); }
                    configManager.setConfiguration(IroncladEventsConfig.GROUP, "useClanSettings", true);
                });
            }
            @Override public void sync() { dispatch(generation, () -> sync.manual(Instant.now())); }
            @Override public void link() { if (running) { linker.start(); } }
            @Override public void cancelLink() { linker.cancel(); }
            @Override public void bank(long event, long precheck, boolean automatic) { dispatch(generation, () -> bank.send(event, precheck, automatic)); }
            @Override public void dismissBank(long event, long precheck) { dispatch(generation, () -> bank.dismiss(event, precheck)); }
            @Override public void capture(Consumer<byte[]> preview)
            { dispatch(generation, () -> pictures.capture(bytes -> SwingUtilities.invokeLater(() -> { if (running && generation == guard.generation()) { preview.accept(bytes); } }))); }
            @Override public void picture(long event, long precheck, String value, String note, byte[] bytes)
            { dispatch(generation, () -> pictures.send(event, precheck, value, note, bytes)); }
            @Override public void respond(long id, String response)
            { if (id >= 0 && Arrays.asList("on_it", "done", "cant").contains(response))
              { dispatch(generation, () -> outbox.submit("captain", "/recommendations/" + id + "/response", Json.obj("response", response), null, ignored -> {})); } }
        };
    }
    @Provides IroncladEventsConfig provideConfig(ConfigManager manager) { return manager.getConfig(IroncladEventsConfig.class); }
}

package com.ironcladrs.events;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.RuneScapeProfileType;

/** Capture on the client thread. No off-thread code reads game state or account identity. */
@Singleton
public class PlayerGuard
{
    @Inject private Client client;
    @Inject private IroncladEventsConfig config;
    private volatile Identity identity;
    private volatile long generation;
    private boolean active;

    public synchronized boolean refresh()
    {
        Identity next = null;
        if (active && config.connect() && config.apiKey().matches("ice_[A-Za-z0-9_-]{43}")
            && client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
            && RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD)
        {
            JsonArray worlds = new JsonArray();
            client.getWorldType().forEach(type -> worlds.add(type.name()));
            next = new Identity(client.getLocalPlayer().getName(), client.getAccountHash(), config.apiKey(), worlds);
        }
        if (!Objects.equals(identity, next)) { identity = next; generation++; return true; }
        return false;
    }
    public Identity identity() { return identity; }
    public long generation() { return generation; }
    public synchronized void activate() { active = true; identity = null; generation++; }
    public synchronized void deactivate() { active = false; identity = null; generation++; }
    public synchronized void clear() { identity = null; generation++; }

    public static final class Identity
    {
        public final String rsn;
        public final long accountHash;
        private final String key;
        private final JsonArray worlds;
        Identity(String rsn, long accountHash, String key, JsonArray worlds)
        { this.rsn = rsn == null ? "" : rsn.replace('\u00a0', ' '); this.accountHash = accountHash; this.key = key; this.worlds = worlds.deepCopy(); }
        public String key() { return key; }
        public JsonObject payload()
        { return Json.obj("rsn", rsn, "accountHash", Long.toString(accountHash), "worldTypes", worlds.deepCopy()); }
        @Override public boolean equals(Object other)
        {
            if (!(other instanceof Identity)) { return false; }
            Identity i = (Identity) other;
            return accountHash == i.accountHash && Objects.equals(rsn, i.rsn) && Objects.equals(key, i.key)
                && worlds.equals(i.worlds);
        }
        @Override public int hashCode() { return Objects.hash(rsn, accountHash, key, worlds); }
        // No toString(): a bearer key must never enter logs.
    }
}

package com.ironcladrs.events;

/** Deaths in a safe place that should still be announced when chosen (as Dink's "Safe Exceptions"). */
public enum SafeDeathException
{
    INFERNO("Inferno"), FIGHT_CAVE("Fight Caves"), JAD_CHALLENGES("Jad challenges"), RAIDS("Raids (CoX, ToB, ToA)"), GAUNTLET("Gauntlet"), DIARY_REVIVE("Diary revives (Fight Caves, Zulrah)");
    private final String label;
    SafeDeathException(String label) { this.label = label; }
    @Override public String toString() { return label; }
    public static SafeDeathException of(String name)
    { for (SafeDeathException e : values()) { if (e.name().equalsIgnoreCase(name == null ? "" : name.trim())) { return e; } } return null; }
}

package com.ironcladrs.events.account;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.ca.CombatAchievementReader;
import com.ironcladrs.events.queue.*;
import java.time.Instant;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/** Account parts share the 12/hour budget. Changes coalesce without ever sending gear or location. */
@Singleton
public class AccountSnapshot
{
    @Inject private Client client;
    @Inject private Consent consent;
    @Inject private Outbox outbox;
    @Inject private CombatAchievementReader ca;
    private JsonObject pending = new JsonObject(), last = new JsonObject();
    private final java.util.Deque<Instant> sent = new ArrayDeque<>();
    private boolean dirty = true;
    private Instant collectAt = Instant.EPOCH;
    private int readyTick;
    private final Map<Skill, Integer> observedLevels = new EnumMap<>(Skill.class);
    public void part(String name, JsonObject value)
    {
        if (!consent.accountPart(name)) { return; }
        if ("collectionLog".equals(name) && !Json.flag(value, "full") && pending.has(name))
        {
            JsonObject existing = Json.object(pending, name); JsonObject merged = Json.object(existing, "items");
            Json.object(value, "items").entrySet().forEach(entry -> merged.add(entry.getKey(), entry.getValue()));
            existing.add("items", merged); if (Json.flag(value, "newItem")) { existing.addProperty("newItem", true); } pending.add(name, existing);
        }
        else if (!value.equals(last.get(name))) { pending.add(name, value.deepCopy()); }
    }
    @Subscribe public void onStatChanged(StatChanged event)
    { if (consent.allows("account") && event.getSkill() != Skill.OVERALL)
      { int level = client.getRealSkillLevel(event.getSkill()); Integer old = observedLevels.put(event.getSkill(), level); if (old == null || old != level) { dirty = true; } } }
    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE || !consent.allows("account")) { return; }
        String text = Text.removeTags(event.getMessage());
        if (text.contains("combat task:") || text.contains("Quest complete") || text.contains("Congratulations, you've completed") || text.contains("diary")) { dirty = true; collectAt = Instant.now().plusSeconds(2); }
    }
    public void tick(Instant now)
    {
        if (!consent.allows("account")) { pending = new JsonObject(); dirty = true; return; }
        if (client.getTickCount() < readyTick) { return; }
        if (dirty && !now.isBefore(collectAt)) { collect(); dirty = false; collectAt = now.plusSeconds(30); }
        while (!sent.isEmpty() && !now.isBefore(sent.peek().plusSeconds(3600))) { sent.remove(); }
        // A part switched off after it was collected never leaves.
        for (String name : new java.util.ArrayList<>(pending.keySet())) { if (!consent.accountPart(name)) { pending.remove(name); } }
        if (pending.size() == 0 || sent.size() >= 12) { return; }
        JsonObject payload = pending.deepCopy(); payload.addProperty("at", now.toString());
        if (outbox.submit("account", "/account", payload, null, result -> { if (!result.success()) { dirty = true; } }))
        { pending.entrySet().forEach(entry -> last.add(entry.getKey(), entry.getValue().deepCopy())); pending = new JsonObject(); sent.add(now); }
    }
    private void collect()
    {
        JsonObject levels = new JsonObject(), quests = new JsonObject(), diaries = new JsonObject();
        for (Skill skill : Skill.values()) { if (skill != Skill.OVERALL) { int level = client.getRealSkillLevel(skill); levels.addProperty(skill.name(), level); observedLevels.put(skill, level); } }
        for (Quest quest : Quest.values()) { quests.add(Integer.toString(quest.getId()), Json.obj("name", quest.getName(), "state", quest.getState(client).name())); }
        // Diary completion flags are sufficient for eligibility; no diary UI or server action is triggered.
        diary(diaries, "Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE);
        diary(diaries, "Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE);
        diary(diaries, "Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE);
        diary(diaries, "Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE);
        diary(diaries, "Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE);
        diary(diaries, "Lumbridge", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE);
        diary(diaries, "Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE);
        diary(diaries, "Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE);
        diary(diaries, "Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE);
        diary(diaries, "Western Provinces", VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE);
        diary(diaries, "Kourend", VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE);
        diary(diaries, "Karamja", net.runelite.api.Varbits.DIARY_KARAMJA_EASY, net.runelite.api.Varbits.DIARY_KARAMJA_MEDIUM, net.runelite.api.Varbits.DIARY_KARAMJA_HARD, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE);
        part("levels", levels); part("quests", quests); part("diaries", diaries);
        JsonObject achievements = ca.capture();
        if (Json.object(achievements, "tiers").size() == 6) { part("combatAchievements", achievements); }
        JsonObject type = Json.obj("ironman", client.getVarbitValue(VarbitID.IRONMAN), "groupSize", client.getVarbitValue(VarbitID.GIM_GROUPSIZE), "hardcoreMain", client.getVarbitValue(VarbitID.HC_MAIN));
        part("accountType", type);
    }
    private void diary(JsonObject result, String name, int... varbits)
    { JsonArray tiers = new JsonArray(); for (int varbit : varbits) { tiers.add(client.getVarbitValue(varbit) != 0); } result.add(name, tiers); }
    public void reset() { pending = new JsonObject(); last = new JsonObject(); sent.clear(); observedLevels.clear(); dirty = true; collectAt = Instant.EPOCH; readyTick = client.getTickCount() + 2; }
}

package com.ironcladrs.events.activity;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.queue.*;
import java.time.Instant;
import java.util.*;
import java.util.regex.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/** Only own game messages and real level changes. Login levels never create achievements. */
@Singleton
public class ActivityCollector
{
    private static final Pattern COMBAT_TASK = Pattern.compile("Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.+?)(?: \\([0-9]+ points?\\))?\\.?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern DIARY = Pattern.compile("Congratulations! You have completed all of the (easy|medium|hard|elite) tasks in the (.+?) area", Pattern.CASE_INSENSITIVE);
    private static final Pattern CLUE = Pattern.compile("You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.", Pattern.CASE_INSENSITIVE);
    @Inject private Client client;
    @Inject private Consent consent;
    @Inject private Outbox outbox;
    @Inject private com.ironcladrs.events.IroncladEventsConfig config;
    @Inject private com.ironcladrs.events.sync.SyncService sync;
    private com.ironcladrs.events.filters.Filters filters() { return new com.ironcladrs.events.filters.Filters(config, sync.state()); }
    /** The level the rules count: real, or virtual (100-126 from XP) when that setting is on. */
    private int levelOf(Skill skill, boolean virtual)
    { return virtual ? Math.min(126, Experience.getLevelForXp(client.getSkillExperience(skill))) : client.getRealSkillLevel(skill); }
    /** Total level always counts real levels, as the game shows it. */
    private int realTotal()
    { int sum = 0; for (Skill skill : Skill.values()) { if (skill != Skill.OVERALL) { sum += client.getRealSkillLevel(skill); } } return sum; }
    private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
    private final Map<String, JsonArray> pending = new LinkedHashMap<>();
    private final LinkedHashSet<String> seen = new LinkedHashSet<>();
    private int total, readyTick;
    private Instant next = Instant.EPOCH;
    private void add(String feature, String signature, JsonObject event)
    {
        if (!consent.allows(feature) || !seen.add(signature)) { return; }
        while (seen.size() > 200) { seen.remove(seen.iterator().next()); }
        JsonArray rows = pending.computeIfAbsent(feature, ignored -> new JsonArray());
        if (rows.size() < 100) { event.addProperty("at", Instant.now().toString()); rows.add(event); }
    }
    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) { return; }
        String text = Text.removeTags(event.getMessage());
        if (text.startsWith("You have a funny feeling like you") || text.startsWith("You feel something weird sneaking"))
        {
            // "...would have been followed" is a pet the player already owns.
            boolean duplicate = text.contains("would have been followed");
            if (!duplicate || filters().petDuplicates) { add("pets", "pet:" + client.getTickCount(), Json.obj("kind", "pet")); }
        }
        Matcher task = COMBAT_TASK.matcher(text);
        if (task.find())
        {
            String tier = task.group(1).toLowerCase(Locale.ROOT), name = task.group(2).trim();
            if (filters().announcesCombatTask(tier)) { add("combatTasks", "ca:" + name.toLowerCase(Locale.ROOT), Json.obj("kind", "ca", "tier", tier, "name", name)); }
        }
        Matcher diary = DIARY.matcher(text);
        if (diary.find())
        {
            String tier = diary.group(1).toLowerCase(Locale.ROOT), area = diary.group(2).trim();
            if (filters().announcesDiary(tier)) { add("diaries", "diary:" + tier + ":" + area.toLowerCase(Locale.ROOT), Json.obj("kind", "diary", "tier", tier, "area", area)); }
        }
        Matcher clue = CLUE.matcher(text);
        if (clue.find())
        {
            try { int count = Integer.parseInt(clue.group(1).replace(",", "")); String tier = clue.group(2).toLowerCase(Locale.ROOT);
                if (!filters().sharesClue(tier)) { return; }
                add("clues", "clue:" + tier + ":" + count, Json.obj("kind", "clue", "tier", tier, "count", count)); }
            catch (NumberFormatException ignored) { /* Invalid game line. */ }
        }
    }
    @Subscribe public void onStatChanged(StatChanged event)
    {
        if (!consent.allows("milestones") || levels.isEmpty() || event.getSkill() == Skill.OVERALL) { return; }
        com.ironcladrs.events.filters.Filters rules = filters();
        Skill skill = event.getSkill(); int level = levelOf(skill, rules.virtualLevels); Integer old = levels.put(skill, level);
        if (old == null || level <= old) { return; }
        // Every level crossed counts, so a multi-level jump still announces the right ones.
        for (int l = old + 1; l <= level; l++)
        { if (rules.announcesLevel(l)) { add("milestones", skill.name() + ":" + l, Json.obj("kind", "level", "skill", skill.name(), "level", l)); } }
        int current = realTotal();
        if (rules.announcesTotal(total, current))
        { int milestone = rules.totalMilestone(current); add("milestones", "total:" + milestone, Json.obj("kind", "total", "level", milestone)); }
        total = current;
    }
    public void tick(Instant now)
    {
        if (client.getTickCount() < readyTick) { return; }
        if (consent.allows("milestones") && levels.isEmpty())
        {
            boolean virtual = filters().virtualLevels;
            for (Skill skill : Skill.values()) { if (skill != Skill.OVERALL) { levels.put(skill, levelOf(skill, virtual)); } }
            total = realTotal();
        }
        if (now.isBefore(next)) { return; }
        for (String feature : new ArrayList<>(pending.keySet()))
        {
            if (!consent.allows(feature)) { pending.remove(feature); continue; }
            JsonArray rows = pending.get(feature), batch = new JsonArray(), rest = new JsonArray();
            for (int i = 0; i < rows.size(); i++) { (i < 20 ? batch : rest).add(rows.get(i)); }
            if (outbox.submit(feature, "/activity", Json.obj("events", batch), null, ignored -> {}))
            { if (rest.size() == 0) { pending.remove(feature); } else { pending.put(feature, rest); } }
        }
        next = now.plusSeconds(3);
    }
    public void reset() { levels.clear(); pending.clear(); seen.clear(); total = 0; readyTick = client.getTickCount() + 2; next = Instant.EPOCH; }
}

package com.ironcladrs.events.api;

import com.google.gson.*;
import com.ironcladrs.events.PlayerGuard;
import com.ironcladrs.events.api.dto.Json;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import okhttp3.*;

/** All outbound traffic is fixed to this HTTPS origin. Redirects are never followed. */
@Singleton
public class ApiClient
{
    public static final String BASE_URL = "https://ironcladrs.com/ingest/plugin/v1";
    public static final String VERSION = "1.0.0";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final int MAX_RESPONSE_BYTES = 2_000_000;
    @Inject private OkHttpClient http;
    @Inject private Gson gson;
    @Inject private ClientThread clientThread;
    private final Set<Call> calls = ConcurrentHashMap.newKeySet();
    private OkHttpClient transport;

    public void request(PlayerGuard.Identity identity, String method, String path, JsonObject payload,
                        byte[] image, String etag, Consumer<Result> callback)
    {
        if (identity == null) { callback.accept(new Result(0, Json.obj("message", "Log in and connect first."), "", false)); return; }
        if (!path.matches("/(hello|sync|loot|death|activity|precheck|precheck/attest|progress|account|pb|chat|session|recommendations/[0-9]+/response)"))
        { throw new IllegalArgumentException("Unsupported plugin endpoint"); }
        if (transport == null) { transport = http.newBuilder().followRedirects(false).followSslRedirects(false).build(); }
        HttpUrl.Builder url = HttpUrl.parse(BASE_URL + path).newBuilder();
        RequestBody body = null;
        JsonObject data = identity.payload();
        if (payload != null) { payload.entrySet().forEach(entry -> data.add(entry.getKey(), entry.getValue().deepCopy())); }
        if ("GET".equals(method))
        {
            url.addQueryParameter("rsn", identity.rsn).addQueryParameter("accountHash", Long.toString(identity.accountHash));
            url.addQueryParameter("worldTypes", data.get("worldTypes").toString());
            if (payload != null && payload.has("since")) { url.addQueryParameter("since", Json.text(payload, "since")); }
        }
        else if (!"DELETE".equals(method))
        {
            String json = gson.toJson(data);
            boolean multipart = path.equals("/loot") || path.equals("/death") || path.equals("/precheck") || path.equals("/pb");
            if (multipart)
            {
                MultipartBody.Builder parts = new MultipartBody.Builder().setType(MultipartBody.FORM)
                    .addFormDataPart("payload", json);
                if (image != null) { parts.addFormDataPart("screenshot", "capture.jpg", RequestBody.create(MediaType.parse("image/jpeg"), image)); }
                body = parts.build();
            }
            else { body = RequestBody.create(JSON, json); }
        }
        Request.Builder request = new Request.Builder().url(url.build()).method(method, body)
            .header("Authorization", "Bearer " + identity.key()).header("X-Ironclad-Plugin", VERSION)
            .header("X-Ironclad-Rsn", identity.rsn).header("X-Ironclad-Account-Hash", Long.toString(identity.accountHash))
            .header("X-Ironclad-World-Types", identity.payload().get("worldTypes").toString());
        if (etag != null && !etag.isEmpty()) { request.header("If-None-Match", etag); }
        Call call = transport.newCall(request.build()); calls.add(call);
        call.enqueue(new Callback()
        {
            @Override public void onFailure(Call failed, java.io.IOException ex)
            { complete(failed, new Result(0, Json.obj("message", "Couldn't reach ironcladrs.com."), "", false)); }
            @Override public void onResponse(Call finished, Response response)
            {
                try (Response closeable = response)
                {
                    JsonObject result = new JsonObject();
                    if (response.code() != 304 && response.body() != null)
                    {
                        okio.BufferedSource source = response.body().source(); source.request(MAX_RESPONSE_BYTES + 1L);
                        if (source.buffer().size() > MAX_RESPONSE_BYTES) { throw new java.io.IOException("Response too large"); }
                        String text = source.readUtf8();
                        if (!text.isEmpty()) { result = gson.fromJson(text, JsonObject.class); }
                    }
                    if (result == null) { result = new JsonObject(); }
                    String retry = response.header("Retry-After");
                    if (retry != null && retry.matches("[0-9]+")) { result.addProperty("retryAfterSec", retry); }
                    complete(finished, new Result(response.code(), result, response.header("ETag", ""), true));
                }
                catch (Exception ex) { complete(finished, new Result(0, Json.obj("message", "The site returned an unreadable response."), "", false)); }
            }
            private void complete(Call finished, Result result)
            {
                calls.remove(finished);
                if (!finished.isCanceled()) { clientThread.invoke(() -> callback.accept(result)); }
            }
        });
    }
    public void cancelAll() { calls.forEach(Call::cancel); calls.clear(); }
    public static final class Result
    {
        public final int status;
        public final JsonObject data;
        public final String etag;
        public final boolean received;
        public Result(int status, JsonObject data, String etag, boolean received)
        { this.status = status; this.data = data; this.etag = etag; this.received = received; }
        public boolean success() { return status >= 200 && status < 300 || status == 409 && "duplicate".equals(Json.text(data, "error")); }
        public boolean retryable() { return status == 0 || status == 429 || status >= 500 && status <= 599; }
        public int retryAfter() { return Json.bounded(data, "retryAfterSec", 5, 1, 600); }
        public String message()
        {
            String text = Json.text(data, "message");
            return text.isEmpty() ? "The site could not accept this request (" + status + ")." : text.substring(0, Math.min(500, text.length()));
        }
    }
}

package com.ironcladrs.events.api.dto;

import com.google.gson.*;
import java.text.Normalizer;
import java.time.Instant;
import java.util.Locale;

/** Defensive accessors keep missing optional server fields from breaking the sidebar. */
public final class Json
{
    private Json() {}
    public static JsonObject object(JsonObject parent, String key)
    {
        JsonElement value = parent.get(key);
        return value != null && value.isJsonObject() ? value.getAsJsonObject() : new JsonObject();
    }
    public static JsonArray array(JsonObject parent, String key)
    {
        JsonElement value = parent.get(key);
        return value != null && value.isJsonArray() ? value.getAsJsonArray() : new JsonArray();
    }
    public static String text(JsonObject parent, String key)
    {
        JsonElement value = parent.get(key);
        return value != null && value.isJsonPrimitive() ? value.getAsString() : "";
    }
    public static long number(JsonObject parent, String key, long fallback)
    {
        try { return parent.has(key) ? parent.get(key).getAsLong() : fallback; }
        catch (RuntimeException ex) { return fallback; }
    }
    public static int bounded(JsonObject parent, String key, int fallback, int min, int max)
    {
        return (int) Math.max(min, Math.min(max, number(parent, key, fallback)));
    }
    public static boolean flag(JsonObject parent, String key)
    {
        return parent.has(key) && parent.get(key).isJsonPrimitive() && "true".equals(parent.get(key).getAsString());
    }
    public static String norm(String value)
    {
        return Normalizer.normalize(value == null ? "" : value, Normalizer.Form.NFKC)
            .replace(' ', ' ').toLowerCase(Locale.ROOT).trim().replaceAll("[\\s_-]+", " ");
    }
    public static Instant time(String value)
    {
        try { return Instant.parse(value); } catch (RuntimeException ex) { return null; }
    }
    public static String safe(String value)
    {
        String text = value == null ? "" : value.replace("<", "").replace(">", "").replaceAll("[\\r\\n]", " ");
        return text.substring(0, Math.min(80, text.length()));
    }
    public static JsonObject obj(Object... pairs)
    {
        JsonObject object = new JsonObject();
        for (int i = 0; i < pairs.length; i += 2)
        {
            Object value = pairs[i + 1]; String key = (String) pairs[i];
            if (value instanceof JsonElement) { object.add(key, (JsonElement) value); }
            else if (value instanceof Number) { object.addProperty(key, (Number) value); }
            else if (value instanceof Boolean) { object.addProperty(key, (Boolean) value); }
            else if (value != null) { object.addProperty(key, value.toString()); }
        }
        return object;
    }
}

package com.ironcladrs.events.ca;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.gameval.VarPlayerID;

/** Task enums and param 1306 are used by the game's ca_tasks_draw_list/4834 scripts.
 * There are no gameval enum/param constants for these in RuneLite 1.13.6. */
@Singleton
public class CombatAchievementReader
{
    private static final int TASK_ID_PARAM = 1306;
    private static final int[] TIER_ENUMS = {3981, 3982, 3983, 3984, 3985, 3986};
    private static final String[] TIERS = {"EASY", "MEDIUM", "HARD", "ELITE", "MASTER", "GRANDMASTER"};
    private static final int[] VARPS = {
        VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
        VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
        VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
        VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
        VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
        VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
        VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19, VarPlayerID.CA_TASK_COMPLETED_20};
    @Inject private Client client;
    public JsonObject capture()
    {
        int[] bits = new int[VARPS.length]; for (int i = 0; i < VARPS.length; i++) { bits[i] = client.getVarpValue(VARPS[i]); }
        JsonObject tiers = new JsonObject(); JsonArray completed = new JsonArray();
        for (int tier = 0; tier < TIERS.length; tier++)
        {
            EnumComposition definitions = client.getEnum(TIER_ENUMS[tier]);
            if (definitions == null || definitions.getIntVals() == null) { continue; }
            int done = 0, total = 0;
            for (int structId : definitions.getIntVals())
            {
                int taskId = client.getStructComposition(structId).getIntValue(TASK_ID_PARAM);
                if (taskId < 0 || taskId / 32 >= bits.length) { continue; }
                total++;
                if (completed(bits, taskId)) { done++; completed.add(taskId); }
            }
            JsonArray progress = new JsonArray(); progress.add(done); progress.add(total); tiers.add(TIERS[tier], progress);
        }
        return Json.obj("tiers", tiers, "completedTaskIds", completed);
    }
    public static boolean completed(int[] bits, int taskId)
    { return taskId >= 0 && taskId / 32 < bits.length && (bits[taskId / 32] & (1 << (taskId % 32))) != 0; }
}

package com.ironcladrs.events.capture;

import com.ironcladrs.events.PlayerGuard;
import com.ironcladrs.events.sync.SyncService;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.Iterator;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.imageio.*;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;

/** Frames and JPEG output stay in memory; encoding never runs on the client thread. */
@Singleton
public class Screenshots
{
    @Inject private DrawManager drawManager;
    @Inject private WorkExecutor work;
    @Inject private ClientThread clientThread;
    @Inject private PlayerGuard guard;
    @Inject private SyncService sync;
    @Inject private com.ironcladrs.events.IroncladEventsConfig config;
    private int pending;
    private final List<Capture> captures = new ArrayList<>();
    public void capture(Consumer<byte[]> callback)
    {
        if (pending >= 3 || guard.identity() == null) { callback.accept(null); return; }
        long generation = guard.generation(); pending++;
        Capture capture = new Capture(generation, callback); captures.add(capture);
        capture.timeout = work.schedule(() -> clientThread.invoke(() -> finish(capture, null)), 5);
        int limit = sync.state().limit("screenshotBytes", 1_500_000, 64_000, 1_500_000);
        int scale = new com.ironcladrs.events.filters.Filters(config, sync.state()).screenshotScale;
        drawManager.requestNextFrameListener(frame -> {
            if (capture.done.get() || generation != guard.generation() || frame.getWidth(null) <= 0 || frame.getHeight(null) <= 0) { return; }
            // DrawManager hands listeners a stable frame; copy before retaining it for background work.
            BufferedImage copy = new BufferedImage(frame.getWidth(null), frame.getHeight(null), BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = copy.createGraphics(); graphics.drawImage(frame, 0, 0, null); graphics.dispose();
            work.execute(() -> {
                byte[] result;
                try { result = encode(copy, limit, scale); } catch (Exception ex) { result = null; }
                final byte[] bytes = result;
                clientThread.invoke(() -> {
                    finish(capture, bytes);
                });
            });
        });
    }
    private void finish(Capture capture, byte[] bytes)
    {
        if (!capture.done.compareAndSet(false, true)) { return; }
        if (capture.timeout != null) { capture.timeout.cancel(false); }
        captures.remove(capture); pending = Math.max(0, pending - 1);
        if (capture.generation == guard.generation()) { capture.callback.accept(bytes); }
    }
    public void reset()
    {
        for (Capture capture : captures)
        { capture.done.set(true); if (capture.timeout != null) { capture.timeout.cancel(false); } }
        captures.clear(); pending = 0;
    }
    private static final class Capture
    {
        final long generation; final Consumer<byte[]> callback; final AtomicBoolean done = new AtomicBoolean();
        ScheduledFuture<?> timeout;
        Capture(long generation, Consumer<byte[]> callback) { this.generation = generation; this.callback = callback; }
    }
    public static byte[] encode(BufferedImage input, int limit) throws java.io.IOException { return encode(input, limit, 100); }
    /** JPEG at most `limit` bytes, shrunk to `percent` of the window first (Screenshot size). */
    public static byte[] encode(BufferedImage input, int limit, int percent) throws java.io.IOException
    {
        int width = Math.max(1, Math.min(1600, input.getWidth() * Math.max(25, Math.min(100, percent)) / 100));
        int height = Math.max(1, input.getHeight() * width / input.getWidth());
        BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = scaled.createGraphics(); graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        graphics.drawImage(input, 0, 0, width, height, null); graphics.dispose();
        for (float quality : new float[]{0.85f, 0.7f})
        {
            Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpeg");
            if (!writers.hasNext()) { return null; }
            ImageWriter writer = writers.next(); ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            try (MemoryCacheImageOutputStream output = new MemoryCacheImageOutputStream(buffer))
            {
                writer.setOutput(output); ImageWriteParam param = writer.getDefaultWriteParam();
                param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT); param.setCompressionQuality(quality);
                writer.write(null, new IIOImage(scaled, null, null), param); output.flush();
            }
            finally { writer.dispose(); }
            if (buffer.size() <= limit) { return buffer.toByteArray(); }
        }
        return null; // Never exceed the advertised upload limit.
    }
}

package com.ironcladrs.events.capture;

import java.util.concurrent.*;
import javax.inject.Singleton;

/** The plugin owns exactly one executor; no feature outlives its lifecycle. */
@Singleton
public class WorkExecutor
{
    private volatile ScheduledExecutorService executor;
    public void start() { executor = Executors.newSingleThreadScheduledExecutor(); }
    public ScheduledFuture<?> repeat(Runnable task) { return executor.scheduleWithFixedDelay(task, 1, 1, TimeUnit.SECONDS); }
    public ScheduledFuture<?> schedule(Runnable task, long seconds)
    {
        ScheduledExecutorService active = executor;
        if (active == null || active.isShutdown()) { return null; }
        try { return active.schedule(task, seconds, TimeUnit.SECONDS); }
        catch (RejectedExecutionException ignored) { return null; }
    }
    public void execute(Runnable task)
    {
        ScheduledExecutorService active = executor;
        if (active != null && !active.isShutdown())
        { try { active.execute(task); } catch (RejectedExecutionException ignored) { /* Stopping. */ } }
    }
    public void stop() { if (executor != null) { executor.shutdownNow(); executor = null; } }
}

package com.ironcladrs.events.chat;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.queue.*;
import com.ironcladrs.events.sync.SyncService;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;

/** The clan channel as Clan Chat Webhooks (clanchat.net) relays it: members' messages and the clan's
 * system broadcasts, with the same message-type codes. Guest, friends, public and private chat never
 * enter the buffer. Nothing is sent unless Connect and Relay clan chat are both on. */
@Singleton
public class ClanChatRelay
{
    @Inject private Client client;
    @Inject private Consent consent;
    @Inject private Outbox outbox;
    @Inject private SyncService sync;
    @Inject private com.ironcladrs.events.IroncladEventsConfig config;
    private JsonArray messages = new JsonArray();
    private Instant due = Instant.EPOCH;
    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (!consent.allows("chat")) { return; }
        ClanChannel channel = client.getClanChannel();
        if (channel == null || !accepts(event.getType(), channel.getName(), sync.state().clanName())) { return; }
        String content = MessageSanitizer.sanitize(event.getMessage());
        int type = systemMessageType(event.getType(), content);
        // A member's message needs its author; the "how to talk in clan chat" login line is never sent.
        String author = MessageSanitizer.sanitize(event.getName()).trim();
        if (content.isEmpty() || type == LOGIN || (type == NORMAL && author.isEmpty()) || messages.size() >= 100) { return; }
        if (type != NORMAL && !new com.ironcladrs.events.filters.Filters(config, sync.state()).relayBroadcasts) { return; }
        messages.add(Json.obj("author", type == NORMAL ? author : "", "content", content, "systemMessageType", type,
            "accountType", accountType(event.getName()), "clanName", channel.getName(), "clanTitle", type == NORMAL ? rankTitle(author) : "",
            "timestamp", Instant.ofEpochSecond(event.getTimestamp())));
        if (messages.size() >= sync.state().limit("chatBatch", 20, 1, 20)) { flush(Instant.now()); }
        else if (messages.size() == 1) { due = Instant.now().plusSeconds(3); }
    }
    public static boolean accepts(ChatMessageType type, String channel, String clan)
    {
        return (type == ChatMessageType.CLAN_CHAT || type == ChatMessageType.CLAN_MESSAGE)
            && !Json.norm(clan).isEmpty() && Json.norm(channel).equals(Json.norm(clan));
    }
    // ── Message types, as Clan Chat Webhooks codes them ──────────────────────
    static final int NORMAL = 1, LOGIN = -1, UNKNOWN = 100;
    public static int systemMessageType(ChatMessageType type, String message)
    {
        if (type != ChatMessageType.CLAN_MESSAGE) { return NORMAL; }
        if (message.contains("received a drop:")) { return 2; }
        if (message.contains("received special loot from a raid:")) { return 3; }
        if (message.contains("has completed a quest:")) { return 7; }
        if (message.contains("received a new collection log item:")) { return 6; }
        if (message.contains("personal best:")) { return 5; }
        if (message.contains("To talk in your clan's channel, start each line of chat with")) { return LOGIN; }
        if (message.contains("has defeated") || message.contains("has been defeated by")) { return 8; }
        if (message.contains("has a funny feeling like") || message.contains("backpack:") || message.contains("something special:")) { return 4; }
        if ((message.contains("has reached") && (message.contains("level") || message.contains("XP"))) || message.contains("has reached a total level of")) { return 10; }
        if (message.contains("tier of rewards from Combat Achievements!") || (message.contains("has completed") && message.contains("combat task"))) { return 11; }
        if (message.contains("received a clue item:")) { return 12; }
        if (message.contains("has left.") || message.contains("has been invited into the clan by") || message.contains("has joined.")) { return 9; }
        if (message.contains("has completed the") && message.contains("diary.")) { return 13; }
        return UNKNOWN;
    }
    // The account-type icon in front of a sender's name (same codes as Clan Chat Webhooks).
    public static int accountType(String name)
    {
        String n = name == null ? "" : name;
        if (n.contains("<img=0>")) { return 8; }
        if (n.contains("<img=2>")) { return 2; }
        if (n.contains("<img=10>")) { return 3; }
        if (n.contains("<img=3>")) { return 4; }
        if (n.contains("<img=41>")) { return 6; }
        if (n.contains("<img=43>")) { return 5; }
        if (n.contains("<img=42>")) { return 7; }
        return 1;
    }
    private String rankTitle(String author)
    {
        ClanChannel channel = client.getClanChannel();
        ClanSettings settings = client.getClanSettings();
        ClanChannelMember member = channel == null ? null : channel.findMember(author);
        ClanTitle title = member == null || settings == null ? null : settings.titleForRank(member.getRank());
        return title == null || title.getName() == null ? "" : title.getName();
    }
    public void tick(Instant now)
    { if (!consent.allows("chat")) { reset(); } else if (!now.isBefore(due)) { flush(now); } }
    private void flush(Instant now)
    {
        if (messages.size() == 0 || !consent.allows("chat")) { return; }
        JsonArray batch = new JsonArray(); int limit = sync.state().limit("chatBatch", 20, 1, 20);
        while (messages.size() > 0 && batch.size() < limit) { batch.add(messages.remove(0)); }
        // Chat is short-lived. One batch remains in the common outbox, bounded by its 15-minute TTL.
        outbox.submit("chat", "/chat", Json.obj("messages", batch), null, ignored -> {}); due = now.plusSeconds(3);
    }
    public void reset() { messages = new JsonArray(); due = Instant.EPOCH; }
}

