package com.ironcladrs.events.death;

import com.ironcladrs.events.SafeDeathException;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * Is a death in this place safe (nothing lost, so not Wall of Shame material)? Dink's list: safe
 * minigames and activities, raids and the Gauntlet for non-hardcore accounts, and the daily diary
 * revive at the Fight Caves and Zulrah. Anything on a hardcore world, or a hardcore account in the
 * hardcore-only cases, is always dangerous. The member (or clan) can choose safe deaths that still count.
 */
public final class SafeDeaths
{
    private SafeDeaths() {}
    private static final Set<Integer> BA_REGIONS = Set.of(7508, 7509, 10322);
    private static final Set<Integer> CASTLE_WARS_REGIONS = Set.of(9520, 9620);
    private static final Set<Integer> CLAN_WARS_REGIONS = Set.of(12621, 12622, 12623, 13130, 13131, 13133, 13134, 13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900, 14155, 14156);
    private static final Set<Integer> COX_REGIONS = Set.of(12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
    private static final Set<Integer> GALVEK_REGIONS = Set.of(6486, 6487, 6488, 6489, 6742, 6743, 6744, 6745);
    private static final Set<Integer> GAUNTLET_REGIONS = Set.of(7512, 7768, 12127);
    private static final Set<Integer> LMS_REGIONS = Set.of(13658, 13659, 13660, 13914, 13915, 13916, 13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
    private static final Set<Integer> POH_REGIONS = Set.of(7257, 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);
    private static final Set<Integer> SOUL_REGIONS = Set.of(8493, 8748, 8749, 9005);
    private static final Set<Integer> TOA_REGIONS = Set.of(14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);
    private static final Set<Integer> TOB_REGIONS = Set.of(12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
    private static final Set<Integer> ZULRAH_REGIONS = Set.of(9007, 9008);
    private static final int INFERNO_REGION = 9043, CREATURE_GRAVEYARD_REGION = 13462, NMZ_REGION = 9033, TZHAAR_CAVE = 9551, CLAN_HALL = 6997, TZHAAR_PIT = 9552;
    private static final int DRAGON_SLAYER_II_COMPLETED = 215;

    /** True when a death at `regionId` should not be announced. */
    public static boolean safe(Client client, int regionId, Set<SafeDeathException> stillCount)
    {
        boolean hardcoreWorld = client.getWorldType().contains(WorldType.HARDCORE_MAIN);
        int ironman = client.getVarbitValue(VarbitID.IRONMAN);
        boolean hardcore = ironman == 3 || ironman == 5, hardcoreGroup = ironman == 5;
        if (GAUNTLET_REGIONS.contains(regionId)) { return !(hardcoreWorld || hardcore) && !stillCount.contains(SafeDeathException.GAUNTLET); }
        if (TOA_REGIONS.contains(regionId) || TOB_REGIONS.contains(regionId)) { return !(hardcoreWorld || hardcore) && !stillCount.contains(SafeDeathException.RAIDS); }
        if (COX_REGIONS.contains(regionId)) { return !(hardcoreWorld || hardcoreGroup) && !stillCount.contains(SafeDeathException.RAIDS); }
        if (regionId == INFERNO_REGION)
        {
            boolean jad = client.getVarpValue(VarPlayerID.SA_ENERGY_STORED) > 0;
            return !(hardcoreWorld || hardcoreGroup) && !stillCount.contains(jad ? SafeDeathException.JAD_CHALLENGES : SafeDeathException.INFERNO);
        }
        if (regionId == TZHAAR_CAVE)
        {
            if (hardcoreWorld || hardcoreGroup || stillCount.contains(SafeDeathException.FIGHT_CAVE)) { return false; }
            boolean revive = client.getVarbitValue(VarbitID.KARAMJA_FIGHTCAVE_RESSURECTION) == 0 && client.getVarbitValue(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE) > 0;
            return !(revive && stillCount.contains(SafeDeathException.DIARY_REVIVE));
        }
        if (ZULRAH_REGIONS.contains(regionId) && client.getVarbitValue(VarbitID.ZULRAH_REVIVE) == 0 && client.getVarbitValue(VarbitID.WESTERN_DIARY_ELITE_COMPLETE) > 0)
        { return !stillCount.contains(SafeDeathException.DIARY_REVIVE); }
        if (BA_REGIONS.contains(regionId) || regionId == NMZ_REGION || regionId == CREATURE_GRAVEYARD_REGION || visible(client, InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2)
            || (GALVEK_REGIONS.contains(regionId) && client.getVarbitValue(VarbitID.DS2) >= DRAGON_SLAYER_II_COMPLETED) || POH_REGIONS.contains(regionId))
        { return !(hardcoreWorld || hardcoreGroup); }
        return CASTLE_WARS_REGIONS.contains(regionId) || regionId == CLAN_HALL || CLAN_WARS_REGIONS.contains(regionId) || SOUL_REGIONS.contains(regionId)
            || LMS_REGIONS.contains(regionId) || visible(client, InterfaceID.BrOverlay.CONTENT) || regionId == TZHAAR_PIT;
    }
    private static boolean visible(Client client, int component)
    { Widget widget = client.getWidget(component); return widget != null && !widget.isHidden(); }
}

package com.ironcladrs.events.filters;

import com.google.gson.JsonObject;
import com.ironcladrs.events.ClueTier;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.loot.LootMatcher;
import com.ironcladrs.events.sync.SessionState;
import java.util.*;

/**
 * Dink-style rules for what is sent (user, 2026-11-27: "more specific like dinks settings", and
 * clan staff setting them on the website). One snapshot per decision: the member's own settings,
 * or, with Use clan filters on, the clan's from the website (any rule the clan left out keeps the
 * member's own). Each feature asks this; nothing here sends anything.
 */
public final class Filters
{
    public final boolean clan;
    public final long screenshotMinValue;
    public final Set<String> alwaysSend, onlyAccounts, ignoredDeathRegions;
    public final boolean sendClueLoot, relayBroadcasts, petDuplicates, virtualLevels;
    public final int levelMinimum, levelInterval, totalLevelInterval, screenshotScale;
    public final ClueTier clueMinTier;
    public final int rarityOverride;
    public final boolean rarityAndValue, sendPkLoot, ignoreSafeDeaths;
    public final Set<com.ironcladrs.events.SafeDeathException> safeDeathExceptions;
    public final com.ironcladrs.events.CombatTaskTier combatTaskMinTier;
    public final com.ironcladrs.events.DiaryTier diaryMinTier;

    public Filters(IroncladEventsConfig config, SessionState state)
    {
        JsonObject preset = Json.object(state.sync(), "clanPreset");
        if (preset.size() == 0) { preset = Json.object(state.hello(), "clanPreset"); }
        clan = config.useClanSettings() && Json.number(preset, "version", 0) == 1;
        JsonObject f = clan ? Json.object(preset, "filters") : new JsonObject();
        alwaysSend = names(text(f, "alwaysSendItems", config.alwaysSendItems()));
        screenshotMinValue = number(f, "screenshotMinValue", config.screenshotMinValue(), 0, Integer.MAX_VALUE);
        sendClueLoot = flag(f, "sendClueLoot", config.sendClueLoot());
        screenshotScale = (int) number(f, "screenshotScale", config.screenshotScale(), 25, 100);
        relayBroadcasts = flag(f, "relayBroadcasts", config.relayBroadcasts());
        ignoredDeathRegions = names(text(f, "ignoredDeathRegions", config.ignoredDeathRegions()));
        petDuplicates = flag(f, "petDuplicates", config.petDuplicates());
        levelMinimum = (int) number(f, "levelMinimum", config.levelMinimum(), 1, 126);
        levelInterval = (int) number(f, "levelInterval", config.levelInterval(), 1, 50);
        virtualLevels = flag(f, "virtualLevels", config.virtualLevels());
        totalLevelInterval = (int) number(f, "totalLevelInterval", config.totalLevelInterval(), 25, 500);
        clueMinTier = f.has("clueMinTier") ? ClueTier.of(Json.text(f, "clueMinTier")) : config.clueMinTier();
        rarityOverride = (int) number(f, "rarityOverride", config.rarityOverride(), 0, 10_000_000);
        rarityAndValue = flag(f, "rarityAndValue", config.rarityAndValue());
        sendPkLoot = flag(f, "sendPkLoot", config.sendPkLoot());
        ignoreSafeDeaths = flag(f, "ignoreSafeDeaths", config.ignoreSafeDeaths());
        if (f.has("safeDeathExceptions"))
        {
            Set<com.ironcladrs.events.SafeDeathException> chosen = EnumSet.noneOf(com.ironcladrs.events.SafeDeathException.class);
            for (String name : Json.text(f, "safeDeathExceptions").split(",")) { com.ironcladrs.events.SafeDeathException e = com.ironcladrs.events.SafeDeathException.of(name); if (e != null) { chosen.add(e); } }
            safeDeathExceptions = chosen;
        }
        else
        {
            Set<com.ironcladrs.events.SafeDeathException> own = config.safeDeathExceptions();
            safeDeathExceptions = own == null || own.isEmpty() ? EnumSet.noneOf(com.ironcladrs.events.SafeDeathException.class) : EnumSet.copyOf(own);
        }
        combatTaskMinTier = f.has("caMinTier") ? com.ironcladrs.events.CombatTaskTier.of(Json.text(f, "caMinTier")) : config.combatTaskMinTier();
        diaryMinTier = f.has("diaryMinTier") ? com.ironcladrs.events.DiaryTier.of(Json.text(f, "diaryMinTier")) : config.diaryMinTier();
        // The account list is always the member's own: it is about their alts, not the clan.
        onlyAccounts = names(config.onlyAccounts());
    }

    // ── Rules ────────────────────────────────────────────────────────────────
    /** An empty list means every linked account. */
    public boolean accountAllowed(String rsn) { return onlyAccounts.isEmpty() || onlyAccounts.contains(LootMatcher.normalize(rsn)); }
    public boolean alwaysSends(String itemName) { return alwaysSend.contains(LootMatcher.normalize(itemName)); }
    public static boolean isClueLoot(String source) { return source != null && source.toLowerCase(Locale.ROOT).startsWith("clue scroll"); }
    /** A level worth announcing: at or above the minimum, on the interval. */
    public boolean announcesLevel(int level) { return level >= levelMinimum && (level - levelMinimum) % levelInterval == 0; }
    /** Crossing a multiple of the interval, from 500 total up. */
    public boolean announcesTotal(int before, int now) { return now >= 500 && now / totalLevelInterval > before / totalLevelInterval; }
    public int totalMilestone(int now) { return now / totalLevelInterval * totalLevelInterval; }
    public boolean sharesClue(String tier) { return ClueTier.of(tier).ordinal() >= clueMinTier.ordinal(); }
    public boolean ignoresDeathIn(int regionId) { return ignoredDeathRegions.contains(Integer.toString(regionId)); }
    /** Rare enough for the override ("1 in N" at least the chosen X)? Off when X is 0. */
    public boolean rare(int oneInN) { return rarityOverride > 0 && oneInN >= rarityOverride; }
    public boolean announcesCombatTask(String tier) { return com.ironcladrs.events.CombatTaskTier.of(tier).ordinal() >= combatTaskMinTier.ordinal(); }
    public boolean announcesDiary(String tier) { return com.ironcladrs.events.DiaryTier.of(tier).ordinal() >= diaryMinTier.ordinal(); }

    // ── Reading the clan's values, falling back to the member's own ─────────
    private static String text(JsonObject f, String key, String own) { return f.has(key) ? Json.text(f, key) : own == null ? "" : own; }
    private static boolean flag(JsonObject f, String key, boolean own) { return f.has(key) ? Json.flag(f, key) : own; }
    private static long number(JsonObject f, String key, long own, long min, long max)
    { long v = f.has(key) ? Json.number(f, key, own) : own; return Math.max(min, Math.min(max, v)); }
    private static Set<String> names(String text)
    {
        Set<String> result = new HashSet<>();
        String bounded = text == null ? "" : text.substring(0, Math.min(1000, text.length()));
        for (String value : bounded.split("[,\\r\\n]")) { if (!value.trim().isEmpty()) { result.add(LootMatcher.normalize(value)); } }
        return result;
    }
}

package com.ironcladrs.events.filters;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;

/**
 * "1 in N" for rare items, sent by ironcladrs.com once per session (from OSRSClans' drop chances, the
 * item's most common source). Replaced whole on each hello; read by the rarity override. Unknown: 0.
 */
@Singleton
public class RarityTable
{
    private volatile Map<Integer, Integer> oneIn = Collections.emptyMap();
    public void update(JsonObject table)
    {
        if (table == null || table.size() == 0) { return; }
        Map<Integer, Integer> next = new HashMap<>();
        for (Map.Entry<String, JsonElement> e : table.entrySet())
        {
            if (next.size() >= 50_000) { break; }
            try { int id = Integer.parseInt(e.getKey()), n = e.getValue().getAsInt(); if (id > 0 && n > 1) { next.put(id, n); } }
            catch (RuntimeException ignored) { /* A malformed entry is skipped. */ }
        }
        oneIn = Collections.unmodifiableMap(next);
    }
    public int oneIn(int itemId) { return oneIn.getOrDefault(itemId, 0); }
}

package com.ironcladrs.events.loot;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.progress.KillCountCollector;
import com.ironcladrs.events.queue.Consent;
import java.time.Instant;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;

/** Collect only the local loot events from §8.1; player loot has no subscription. */
@Singleton
public class LootCollector
{
    @Inject private Client client;
    @Inject private ItemManager items;
    @Inject private KillCountCollector kc;
    @Inject private LootSubmitter submitter;
    @Inject private Consent consent;
    @Subscribe public void onServerNpcLoot(ServerNpcLoot event)
    {
        if (!consent.allows("loot")) { return; }
        collect(event.getItems(), event.getComposition().getName(), "NPC", event.getComposition().getId());
    }
    /** Loot from a player kill: the other player's name never leaves the client (only "Player kill"). */
    @Subscribe public void onPlayerLootReceived(PlayerLootReceived event)
    {
        if (!consent.allows("loot")) { return; }
        collect(event.getItems(), "Player kill", "PLAYER", null);
    }
    @Subscribe public void onLootReceived(LootReceived event)
    {
        if (consent.allows("loot") && (event.getType() == LootRecordType.EVENT || event.getType() == LootRecordType.PICKPOCKET))
        { collect(event.getItems(), event.getName(), event.getType().name(), null); }
    }
    private void collect(Collection<ItemStack> stacks, String name, String type, Integer npcId)
    {
        if (name == null) { return; }
        KillCountCollector.Count count = kc.recent(name, client.getTickCount());
        String sourceName = count != null && count.name.startsWith(name + ":") ? count.name : name;
        JsonObject source = Json.obj("type", type, "name", sourceName, "npcId", npcId);
        if (count != null) { source.addProperty("killCount", count.count); }
        Map<Integer, Long> reduced = stack(stacks);
        JsonArray serialized = new JsonArray();
        reduced.forEach((id, quantity) -> serialized.add(Json.obj("id", id,
            "name", items.getItemComposition(id).getMembersName(), "quantity", quantity, "priceEach", items.getItemPrice(id))));
        if (serialized.size() > 0) { submitter.submit(source, serialized, Instant.now()); }
    }
    public static Map<Integer, Long> stack(Collection<ItemStack> stacks)
    {
        Map<Integer, Long> reduced = new LinkedHashMap<>();
        for (ItemStack item : stacks) { if (item.getId() >= 0 && item.getQuantity() > 0) { reduced.merge(item.getId(), (long) item.getQuantity(), Long::sum); } }
        return reduced;
    }
}

package com.ironcladrs.events.loot;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.sync.SessionState;
import java.time.Instant;

/** Event matching never evaluates game rules; the server remains the authority. */
public final class LootMatcher
{
    private LootMatcher() {}
    public static boolean matches(JsonArray events, long wallMinGp, String source, JsonArray items, Instant at)
    {
        long value = 0;
        for (JsonElement item : items)
        {
            JsonObject i = item.getAsJsonObject();
            long price = Math.max(0, Json.number(i, "priceEach", 0)), qty = Math.max(0, Json.number(i, "quantity", 0));
            if (qty > 0 && price > (Long.MAX_VALUE - value) / qty) { value = Long.MAX_VALUE; }
            else { value += price * qty; }
        }
        if (wallMinGp >= 0 && value >= wallMinGp) { return true; }
        for (JsonElement valueEvent : events)
        {
            if (!valueEvent.isJsonObject()) { continue; }
            JsonObject event = valueEvent.getAsJsonObject();
            if (!SessionState.inWindow(event, at)) { continue; }
            JsonObject match = Json.object(event, "match");
            if ("all".equals(Json.text(match, "mode")) || contains(Json.array(match, "sources"), source)) { return true; }
            for (JsonElement item : items)
            {
                JsonObject i = item.getAsJsonObject();
                if (contains(Json.array(match, "itemIds"), Json.text(i, "id")) || contains(Json.array(match, "names"), Json.text(i, "name"))) { return true; }
            }
        }
        return false;
    }
    public static String normalize(String value)
    { return Json.norm(value).replaceAll("['‘’ʼ`“”\"]", ""); }
    private static boolean contains(JsonArray values, String needle)
    { for (JsonElement value : values) { if (value.isJsonPrimitive() && normalize(value.getAsString()).equals(normalize(needle))) { return true; } } return false; }
}

package com.ironcladrs.events.loot;

import com.google.gson.*;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.sync.SessionState;
import java.util.*;

/** Filters never alter the item list used by Dink de-duplication or enable uploads. */
public final class LootPolicy
{
    public final int minimumWallValue;
    public final String ignoredItems, ignoredSources;
    public final boolean clan;
    public LootPolicy(IroncladEventsConfig config, SessionState state)
    {
        JsonObject preset = Json.object(state.sync(), "clanPreset");
        if (preset.size() == 0) { preset = Json.object(state.hello(), "clanPreset"); }
        clan = config.useClanSettings() && Json.number(preset, "version", 0) == 1;
        JsonObject filters = Json.object(preset, "filters");
        minimumWallValue = clan ? Json.bounded(filters, "minimumWallValue", 0, 0, Integer.MAX_VALUE) : Math.max(0, config.minimumWallValue());
        ignoredItems = bounded(clan ? Json.text(filters, "ignoredLootItems") : config.ignoredLootItems());
        ignoredSources = bounded(clan ? Json.text(filters, "ignoredLootSources") : config.ignoredLootSources());
    }
    private static String bounded(String value) { return value == null ? "" : value.substring(0, Math.min(500, value.length())); }
    public long wallMinimum(long serverMinimum) { return Math.max(serverMinimum, minimumWallValue); }
    public boolean ignores(String source, JsonArray items)
    {
        if (names(ignoredSources).contains(LootMatcher.normalize(source))) { return true; }
        Set<String> ignored = names(ignoredItems);
        if (items.size() == 0) { return false; }
        for (JsonElement value : items)
        { if (!value.isJsonObject() || !ignored.contains(LootMatcher.normalize(Json.text(value.getAsJsonObject(), "name")))) { return false; } }
        return true;
    }
    private static Set<String> names(String text)
    {
        Set<String> result = new HashSet<>();
        for (String value : text.split("[,\\r\\n]")) { if (!value.trim().isEmpty()) { result.add(LootMatcher.normalize(value)); } }
        return result;
    }
}

package com.ironcladrs.events.loot;

import com.google.gson.*;
import com.ironcladrs.events.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.capture.Screenshots;
import com.ironcladrs.events.notice.ChatNotices;
import com.ironcladrs.events.queue.*;
import com.ironcladrs.events.sync.SyncService;
import java.time.Instant;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

/** A screenshot failure never loses a qualifying drop; Dink can still provide later proof. */
@Singleton
public class LootSubmitter
{
    @Inject private IroncladEventsConfig config;
    @Inject private PlayerGuard guard;
    @Inject private Consent consent;
    @Inject private SyncService sync;
    @Inject private Outbox outbox;
    @Inject private Screenshots screenshots;
    @Inject private ChatNotices notices;
    @Inject private com.ironcladrs.events.filters.RarityTable rarity;
    public void submit(JsonObject source, JsonArray items, Instant at)
    {
        LootPolicy policy = new LootPolicy(config, sync.state());
        if (!consent.allows("loot") || policy.ignores(Json.text(source, "name"), items)) { return; }
        com.ironcladrs.events.filters.Filters filters = new com.ironcladrs.events.filters.Filters(config, sync.state());
        if (!filters.sendClueLoot && com.ironcladrs.events.filters.Filters.isClueLoot(Json.text(source, "name"))) { return; }
        boolean pk = "PLAYER".equals(Json.text(source, "type"));
        if (pk && !filters.sendPkLoot) { return; }
        long total = 0; boolean always = false; int rarest = 0;
        for (JsonElement value : items)
        {
            if (!value.isJsonObject()) { continue; } JsonObject item = value.getAsJsonObject();
            total += Json.number(item, "quantity", 0) * Json.number(item, "priceEach", 0); always |= filters.alwaysSends(Json.text(item, "name"));
            rarest = Math.max(rarest, rarity.oneIn((int) Json.number(item, "id", 0)));
        }
        boolean rare = !pk && filters.rare(rarest);
        // Event tiles and the Wall of Fame are separate switches. A drop that matches an event only goes
        // while Event tile drops is on, because sending it would file a claim.
        String name = Json.text(source, "name");
        boolean event = LootMatcher.matches(sync.state().events(), -1, name, items, at);
        boolean valued = LootMatcher.matches(new JsonArray(), policy.wallMinimum(Json.number(Json.object(sync.state().hello(), "wall"), "minGp", Long.MAX_VALUE)), name, items, at);
        // Rare drops skip the value minimum unless "Rare drops must also meet value" is on.
        boolean viaRarity = rare && (!filters.rarityAndValue || valued);
        boolean wall = always || viaRarity || valued;
        if (pk) { event = false; }
        if (event ? !config.autoDrops() : !(wall && config.wallOfFameDrops())) { return; }
        long generation = guard.generation();
        JsonObject payload = Json.obj("occurredAt", at, "source", source, "items", items, "wallOfFame", config.wallOfFameDrops());
        // Tells the site why a drop below the minimum was sent, so it still reaches the wall.
        if (!valued && (always || viaRarity)) { payload.addProperty("wallReason", always ? "always" : "rare"); }
        Consumer<byte[]> send = image -> {
            if (generation != guard.generation() || !consent.allows("loot")) { return; }
            outbox.submit("loot", "/loot", payload, image, result -> {
                if (!result.success() || Json.flag(result.data, "duplicate")) { return; }
                String item = Json.text(items.get(0).getAsJsonObject(), "name");
                for (JsonElement filed : Json.array(result.data, "filed")) { if (filed.isJsonObject()) { notices.filed(item, Json.text(filed.getAsJsonObject(), "label"), Json.text(filed.getAsJsonObject(), "kind") + ":" + Json.text(filed.getAsJsonObject(), "id")); } }
            });
        };
        // Event drops always carry proof; other drops only from the screenshot minimum up.
        if (config.screenshots() && (event || rare || total >= filters.screenshotMinValue)) { screenshots.capture(send); } else { send.accept(null); }
    }
}

package com.ironcladrs.events.notice;

import com.google.gson.*;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;

/** Only fixed templates go into RuneLite chat; remote values cannot inject formatting. */
@Singleton
public class ChatNotices
{
    @Inject private Client client;
    @Inject private Notifier notifier;
    @Inject private IroncladEventsConfig config;
    private final LinkedHashSet<String> seen = new LinkedHashSet<>();
    private boolean initialized;
    private final LinkedHashSet<String> recordedClaims = new LinkedHashSet<>();
    public void reset() { seen.clear(); recordedClaims.clear(); initialized = false; }
    public void line(String text)
    { if (config.chatNotices()) { client.addChatMessage(ChatMessageType.CONSOLE, "", "Ironclad: " + text, null); } }
    public void queued(int count) { line("couldn't reach the site; " + count + " item(s) queued."); }
    public void filed(String item, String label) { line("filed " + Json.safe(item) + " for " + Json.safe(label) + ". Waiting for staff."); }
    public void filed(String item, String label, String claimKey)
    {
        if (!recordedClaims.add(claimKey)) { return; }
        while (recordedClaims.size() > 500) { recordedClaims.remove(recordedClaims.iterator().next()); }
        filed(item,label);
    }
    public void pb(String boss, String time) { line("new personal best at " + Json.safe(boss) + ", " + Json.safe(time) + ", sent for approval."); }
    public void accept(JsonArray notices)
    {
        int n = 0;
        for (JsonElement value : notices)
        {
            if (++n > 50 || !value.isJsonObject()) { break; }
            JsonObject notice = value.getAsJsonObject(); String id = Json.text(notice, "id");
            if (id.isEmpty() || !seen.add(id) || !initialized) { continue; }
            String kind = Json.text(notice, "kind"), item = Json.safe(Json.text(notice, "item")), label = Json.safe(Json.text(notice, "label"));
            String reason = Json.safe(Json.text(notice, "reason"));
            switch (kind)
            {
                case "claim_recorded": filed(item, label, Json.text(notice, "claimKind") + ":" + Json.text(notice, "claimId")); break;
                case "claim_approved":
                    JsonArray lines = Json.array(notice, "lines");
                    line(item + " approved for " + label + ". " + (lines.size() > 0 ? Json.safe(lines.get(0).getAsString()) : "")); break;
                case "claim_denied": line(item + " for " + label + " was denied: " + reason); break;
                case "precheck_passed": line("precheck \"" + label + "\" passed."); break;
                case "precheck_needs_review": line("precheck \"" + label + "\" needs a staff look."); break;
                case "progress_mismatch": line("WOM hasn't caught up; log out to the lobby to update the hiscores."); break;
                default: break;
            }
            if (config.desktopNotices() && Arrays.asList("event_starting", "event_started", "door_open", "priority_changed", "claim_approved", "claim_denied", "pb_approved", "pb_denied").contains(kind))
            { notifier.notify("Ironclad: " + kind.replace('_', ' ') + (label.isEmpty() ? "" : " · " + label)); }
        }
        initialized = true;
        while (seen.size() > 500) { seen.remove(seen.iterator().next()); }
    }
}

package com.ironcladrs.events.pb;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;

/** The only worn-gear serializer. No inventory, bank or other player equipment is retained. */
@Singleton
public class GearSnapshot
{
    @Inject private Client client;
    public JsonObject capture()
    {
        JsonObject gear = new JsonObject(), levels = new JsonObject(); ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        if (worn != null)
        {
            for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
            {
                if (slot == EquipmentInventorySlot.RING || slot == EquipmentInventorySlot.AMMO || slot == EquipmentInventorySlot.HEAD
                    || slot == EquipmentInventorySlot.CAPE || slot == EquipmentInventorySlot.AMULET || slot == EquipmentInventorySlot.WEAPON
                    || slot == EquipmentInventorySlot.BODY || slot == EquipmentInventorySlot.SHIELD || slot == EquipmentInventorySlot.LEGS
                    || slot == EquipmentInventorySlot.GLOVES || slot == EquipmentInventorySlot.BOOTS)
                { Item item = worn.getItem(slot.getSlotIdx()); if (item != null && item.getId() > 0) { gear.addProperty(slot.name(), item.getId()); } }
            }
        }
        for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.PRAYER, Skill.MAGIC})
        { levels.addProperty(skill.name(), client.getRealSkillLevel(skill)); }
        return Json.obj("gear", gear, "levels", levels);
    }
}

package com.ironcladrs.events.pb;

import com.google.gson.*;
import com.ironcladrs.events.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.capture.Screenshots;
import com.ironcladrs.events.notice.ChatNotices;
import com.ironcladrs.events.progress.KillCountCollector;
import com.ironcladrs.events.queue.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import java.util.regex.*;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/** Pair completion timing with the game's KC line; never infer a PB during combat. */
@Singleton
public class PersonalBestListener
{
    private static final Pattern TIME = Pattern.compile("(?:Duration|time|Subdued in):? ([0-9:]+(?:\\.[0-9]+)?)", Pattern.CASE_INSENSITIVE);
    @Inject private Client client;
    @Inject private IroncladEventsConfig config;
    @Inject private PlayerGuard guard;
    @Inject private Consent consent;
    @Inject private Outbox outbox;
    @Inject private KillCountCollector kc;
    @Inject private GearSnapshot gear;
    @Inject private Screenshots screenshots;
    @Inject private ChatNotices notices;
    private JsonObject pending;
    private int pendingTick;
    private final Set<String> sent = new HashSet<>();
    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (!consent.allows("pbs")) { return; }
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION) { return; }
        String text = Text.removeTags(event.getMessage()); Long time = parseNewBest(text);
        if (time == null || text.startsWith("Preparation")) { return; }
        // TOB's wave time can precede challenge time in the same message.
        int challenge = text.indexOf("Theatre of Blood");
        if (text.startsWith("Wave") && challenge >= 0) { time = parseNewBest(text.substring(challenge)); if (time == null) { return; } }
        if (pending != null && pendingTick == client.getTickCount()) { return; }
        pending = gear.capture(); pending.addProperty("timeMs", time); pending.addProperty("at", Instant.now().toString()); pendingTick = client.getTickCount();
    }
    @Subscribe public void onGameTick(GameTick event)
    {
        if (pending == null) { return; }
        int tick = client.getTickCount();
        if (!consent.allows("pbs") || tick - pendingTick > 1) { pending = null; return; }
        KillCountCollector.Count count = kc.latest(tick);
        if (count == null) { return; }
        JsonObject payload = pending; pending = null;
        payload.addProperty("boss", count.name); payload.addProperty("killCount", count.count); payload.addProperty("teamSize", teamSize(count.name));
        String unique = count.name + ":" + count.count + ":" + Json.number(payload, "timeMs", 0);
        if (!sent.add(unique)) { return; }
        if (sent.size() > 100) { sent.clear(); sent.add(unique); }
        long generation = guard.generation();
        Consumer<byte[]> send = image -> {
            if (generation == guard.generation() && consent.allows("pbs"))
            { outbox.submit("pbs", "/pb", payload, image, result -> { if (result.success() && result.status != 409 && !Json.flag(result.data, "duplicate")) { notices.pb(count.name, format(Json.number(payload, "timeMs", 0))); } }); }
        };
        if (config.pbScreenshots()) { screenshots.capture(send); } else { send.accept(null); }
    }
    public static Long parseNewBest(String text)
    {
        // "Personal best: 1:23" alone reports an old PB; only the new-PB marker proves a new record.
        if (!text.toLowerCase(Locale.ROOT).contains("(new personal best)")) { return null; }
        Matcher matcher = TIME.matcher(text); if (!matcher.find()) { return null; }
        try
        {
            String[] components = matcher.group(1).split(":"); if (components.length > 3) { return null; }
            BigDecimal seconds = BigDecimal.ZERO;
            for (String part : components) { seconds = seconds.multiply(BigDecimal.valueOf(60)).add(new BigDecimal(part)); }
            long ms = seconds.multiply(BigDecimal.valueOf(1000)).longValueExact(); return ms > 0 && ms < 86_400_000 ? ms : null;
        }
        catch (ArithmeticException | NumberFormatException ex) { return null; }
    }
    private int teamSize(String name)
    {
        if (name.startsWith("Chambers of Xeric")) { return Math.max(1, Math.min(100, client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE))); }
        int[] members = name.startsWith("Tombs of Amascut")
            ? new int[]{VarbitID.TOA_CLIENT_P1, VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3, VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5, VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7}
            : name.startsWith("Theatre of Blood") ? new int[]{VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4} : new int[0];
        int size = 1; for (int varbit : members) { if (client.getVarbitValue(varbit) != 0) { size++; } } return size;
    }
    public static String format(long ms) { return (ms / 60000) + ":" + String.format(Locale.ROOT, "%06.3f", (ms % 60000) / 1000.0); }
    public void reset() { pending = null; sent.clear(); }
}

package com.ironcladrs.events.precheck;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.queue.*;
import com.ironcladrs.events.sync.SyncService;
import java.time.Instant;
import java.util.*;
import java.util.function.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/** Only an open bank can create evidence. The full containers never enter an upload DTO. */
@Singleton
public class BankAttestor
{
    @Inject private Client client;
    @Inject private ItemManager items;
    @Inject private SyncService sync;
    @Inject private Consent consent;
    @Inject private Outbox outbox;
    private final Map<String, JsonObject> cards = new LinkedHashMap<>();
    private final Set<Long> automatic = new HashSet<>();
    private final Set<String> submitted = new HashSet<>();
    private final Set<String> dismissed = new HashSet<>();
    private Consumer<Map<String, JsonObject>> listener = ignored -> {};
    @Subscribe public void onWidgetLoaded(WidgetLoaded event)
    { if (event.getGroupId() == InterfaceID.BANKMAIN) { dismissed.clear(); } }
    public void listen(Consumer<Map<String, JsonObject>> listener) { this.listener = listener; }
    @Subscribe public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (!consent.allows("bankPrechecks")) { return; }
        if (event.getContainerId() != InventoryID.BANK && cards.isEmpty()) { return; }
        if (event.getContainerId() != InventoryID.BANK && event.getContainerId() != InventoryID.INV && event.getContainerId() != InventoryID.WORN) { return; }
        ItemContainer bank = client.getItemContainer(InventoryID.BANK), inventory = client.getItemContainer(InventoryID.INV), worn = client.getItemContainer(InventoryID.WORN);
        if (bank == null || inventory == null || worn == null) { return; }
        cards.clear();
        for (JsonElement eventValue : sync.state().events())
        {
            if (!eventValue.isJsonObject()) { continue; }
            JsonObject eventData = eventValue.getAsJsonObject(); long eventId = Json.number(eventData, "id", -1);
            Instant end = Json.time(Json.text(eventData, "endsAt"));
            if (eventId < 0 || end == null || !Instant.now().isBefore(end)) { continue; }
            for (JsonElement value : Json.array(eventData, "prechecksOwed"))
            {
                if (!value.isJsonObject()) { continue; }
                JsonObject precheck = value.getAsJsonObject();
                if (!"bank".equals(Json.text(precheck, "kind"))) { continue; }
                long precheckId = Json.number(precheck, "id", -1); String key = key(eventId, precheckId);
                if (precheckId < 0 || submitted.contains(key) || dismissed.contains(key)) { continue; }
                JsonArray asked = Json.array(Json.object(precheck, "ask"), "itemIds");
                if (asked.size() == 0 || asked.size() > 100) { continue; }
                JsonObject counts = count(asked, Arrays.asList(bank.getItems(), inventory.getItems(), worn.getItems()), items::canonicalize);
                JsonObject card = Json.obj("eventId", eventId, "precheckId", precheckId, "label", Json.text(precheck, "label"), "counts", counts, "at", Instant.now());
                JsonObject names = new JsonObject();
                counts.keySet().forEach(id -> names.addProperty(id, items.getItemComposition(Integer.parseInt(id)).getMembersName()));
                card.add("names", names); cards.put(key, card);
            }
        }
        for (JsonObject card : new ArrayList<>(cards.values()))
        { if (automatic.contains(Json.number(card, "eventId", -1))) { send(Json.number(card, "eventId", -1), Json.number(card, "precheckId", -1), false); } }
        publish();
    }
    public static JsonObject count(JsonArray asked, List<Item[]> containers, IntUnaryOperator canonicalize)
    {
        Map<Integer, Integer> askedCanonical = new LinkedHashMap<>(); JsonObject result = new JsonObject();
        for (JsonElement value : asked)
        { int id = value.getAsInt(); if (id > 0) { askedCanonical.put(id, canonicalize.applyAsInt(id)); result.addProperty(Integer.toString(id), 0L); } }
        for (Item[] container : containers)
        { for (Item item : container)
        { if (item == null || item.getId() < 0 || item.getQuantity() <= 0) { continue; }
          int id = canonicalize.applyAsInt(item.getId());
          askedCanonical.forEach((askedId, canonical) -> { if (id == canonical) { String key = askedId.toString(); result.addProperty(key, result.get(key).getAsLong() + item.getQuantity()); } });
        } }
        return result;
    }
    public void send(long eventId, long precheckId, boolean automatically)
    {
        String key = key(eventId, precheckId); JsonObject card = cards.get(key);
        if (card == null || !consent.allows("bankPrechecks")) { return; }
        // Expired cards require a fresh bank event; do not attest against stale inventory.
        Instant at = Json.time(Json.text(card, "at"));
        if (at == null || at.plusSeconds(120).isBefore(Instant.now())) { cards.remove(key); publish(); return; }
        JsonArray sources = new JsonArray(); sources.add("bank"); sources.add("inventory"); sources.add("equipment");
        JsonObject payload = card.deepCopy(); payload.remove("label"); payload.remove("names"); payload.add("sources", sources);
        if (outbox.submit("bankPrechecks", "/precheck/attest", payload, null, result -> {
            if (!result.success()) { submitted.remove(key); }
        }))
        { submitted.add(key); cards.remove(key); if (automatically) { automatic.add(eventId); } publish(); }
    }
    public void dismiss(long eventId, long precheckId)
    { String key = key(eventId, precheckId); dismissed.add(key); cards.remove(key); publish(); }
    public void reset() { cards.clear(); automatic.clear(); submitted.clear(); dismissed.clear(); publish(); }
    private static String key(long eventId, long precheckId) { return eventId + ":" + precheckId; }
    private void publish()
    {
        Map<String, JsonObject> copy = new LinkedHashMap<>(); cards.forEach((key, value) -> copy.put(key, value.deepCopy()));
        listener.accept(Collections.unmodifiableMap(copy));
    }
}

