package com.ironcladrs.events.queue;

import com.ironcladrs.events.*;
import com.ironcladrs.events.sync.SyncService;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Rechecked for every attempt, including jobs captured before a switch changed. */
@Singleton
public class Consent
{
    @Inject private PlayerGuard guard;
    @Inject private IroncladEventsConfig config;
    @Inject private SyncService sync;
    public boolean allows(String feature)
    {
        guard.refresh();
        String server = feature.equals("combatTasks") || feature.equals("diaries") ? "milestones" : feature;
        if (!config.connect() || guard.identity() == null || !sync.current() || !sync.state().feature(server)) { return false; }
        if (!new com.ironcladrs.events.filters.Filters(config, sync.state()).accountAllowed(guard.identity().rsn)) { return false; }
        switch (feature)
        {
            case "loot": return config.autoDrops() || config.wallOfFameDrops();
            case "combatTasks": return config.shareCombatTasks();
            case "diaries": return config.shareDiaries();
            case "prechecks": return true;
            case "bankPrechecks": return config.bankPrechecks();
            case "captain": return true;
            case "progress": return config.liveProgress();
            case "account": return config.syncCollectionLog() || config.syncCombatAchievements() || config.syncQuests() || config.syncLevels();
            case "pbs": return config.autoPbs();
            case "chat": return config.relayClanChat();
            case "deaths": return config.autoDeaths();
            case "pets": return config.sharePets();
            case "milestones": return config.shareMilestones();
            case "clues": return config.shareClues();
            default: return false;
        }
    }
    /** Each part of the account snapshot has its own switch; quests travel with diaries, levels with account type. */
    public boolean accountPart(String part)
    {
        if (!allows("account")) { return false; }
        switch (part)
        {
            case "collectionLog": return config.syncCollectionLog();
            case "combatAchievements": return config.syncCombatAchievements();
            case "quests": case "diaries": return config.syncQuests();
            case "levels": case "accountType": return config.syncLevels();
            default: return false;
        }
    }

}

package com.ironcladrs.events.queue;

import com.google.gson.*;
import com.ironcladrs.events.*;
import com.ironcladrs.events.api.ApiClient;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.notice.ChatNotices;
import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Memory-only queue, confined to the client thread. Entries never cross identity generations. */
@Singleton
public class Outbox
{
    public static final int CAPACITY = 30;
    @Inject private ApiClient api;
    @Inject private PlayerGuard guard;
    @Inject private Consent consent;
    @Inject private IroncladEventsConfig config;
    @Inject private ChatNotices notices;
    @Inject private com.ironcladrs.events.sync.SyncService sync;
    private final Deque<Entry> entries = new ArrayDeque<>();
    private long generation = -1;
    private Instant nextAttempt = Instant.EPOCH;
    private boolean busy, outage;
    private Consumer<String> status = ignored -> {};

    public void listen(Consumer<String> listener) { status = listener; }
    public int size() { return entries.size(); }
    public void clear() { entries.clear(); busy = false; outage = false; generation = guard.generation(); nextAttempt = Instant.EPOCH; }
    public boolean submit(String feature, String path, JsonObject data, byte[] screenshot, Consumer<ApiClient.Result> callback)
    {
        if (!consent.allows(feature)) { status.accept("Enable this upload in settings first, and check the connection."); return false; }
        if (generation != guard.generation()) { clear(); }
        if (entries.size() >= CAPACITY) { status.accept("Upload queue full. Please use the site for this submission."); return false; }
        JsonObject payload = data.deepCopy();
        if (!payload.has("idempotencyKey")) { payload.addProperty("idempotencyKey", UUID.randomUUID().toString()); }
        entries.add(new Entry(feature, path, payload, screenshot, Instant.now(), callback));
        pump(Instant.now()); return true;
    }
    public void pump(Instant now)
    {
        if (generation != guard.generation()) { clear(); }
        if (busy || entries.isEmpty() || now.isBefore(nextAttempt)) { return; }
        Entry entry = entries.peek();
        if (!consent.allows(entry.feature) || now.isAfter(entry.created.plusSeconds(900)))
        { entries.remove(); status.accept("An unsent upload was discarded after consent changed or it expired."); return; }
        if (now.isBefore(entry.due)) { return; }
        if (entry.attempts >= 3 && (sync.state().syncedAt == null || sync.state().syncedAt.isBefore(entry.due))) { return; }
        busy = true; long expected = generation;
        // Each feature has its own screenshot switch, re-read at send time; precheck pictures are always asked for.
        boolean pictures = "deaths".equals(entry.feature) ? config.deathScreenshots() : "pbs".equals(entry.feature) ? config.pbScreenshots()
            : "loot".equals(entry.feature) ? config.screenshots() : "prechecks".equals(entry.feature);
        byte[] image = pictures ? entry.image : null;
        if ("/precheck".equals(entry.path) && image == null) { busy = false; entries.remove(); return; }
        api.request(guard.identity(), "POST", entry.path, entry.payload, image, null, result -> {
            if (expected != guard.generation()) { return; } busy = false;
            if (result.success())
            {
                entries.remove(entry); outage = false; entry.callback.accept(result);
                status.accept(result.status == 409 ? "Already received by the site." : "Received by the site.");
            }
            else if (result.retryable())
            {
                entry.attempts++; entry.due = Instant.now().plusSeconds(Math.max(delay(entry.attempts), result.status == 429 ? result.retryAfter() : 0));
                nextAttempt = entry.due;
                if (!outage) { outage = true; notices.queued(entries.size()); }
                status.accept("Couldn't reach the site; " + entries.size() + " upload(s) queued.");
            }
            else { entries.remove(entry); status.accept(result.message()); entry.callback.accept(result); }
        });
    }
    public static int delay(int attempt) { return attempt <= 1 ? 5 : attempt == 2 ? 15 : 60; }
    private static final class Entry
    {
        final String feature, path; final JsonObject payload; final byte[] image;
        final Instant created; final Consumer<ApiClient.Result> callback;
        Instant due = Instant.EPOCH; int attempts;
        Entry(String feature, String path, JsonObject payload, byte[] image, Instant created, Consumer<ApiClient.Result> callback)
        { this.feature = feature; this.path = path; this.payload = payload; this.image = image; this.created = created; this.callback = callback; }
    }
}

package com.ironcladrs.events.sync;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.capture.WorkExecutor;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledFuture;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.*;

/**
 * Links this plugin to a member's account without copying a key. Only runs while Connect is on, so the
 * third-party warning has been accepted first. The site hands the key to whoever holds the private poll
 * secret, which never leaves this object; the key goes straight into the Plugin key setting.
 */
@Slf4j
@Singleton
public class AccountLinker
{
    public static final String BASE_URL = "https://ironcladrs.com/api/plugin-link";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final int MAX_RESPONSE_BYTES = 10_000;

    /** What the panel shows. Immutable so the Swing thread can read it safely. */
    public static final class State
    {
        public enum Phase { IDLE, STARTING, WAITING, LINKED, FAILED }
        public final Phase phase; public final String code, url, message;
        public State(Phase phase, String code, String url, String message) { this.phase = phase; this.code = code; this.url = url; this.message = message; }
        public static final State IDLE_STATE = new State(Phase.IDLE, "", "", "");
    }

    @Inject private OkHttpClient http;
    @Inject private Gson gson;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private IroncladEventsConfig config;
    @Inject private WorkExecutor work;
    private final Set<Call> calls = ConcurrentHashMap.newKeySet();
    private volatile Consumer<State> listener = state -> {};
    private volatile State state = State.IDLE_STATE;
    private volatile ScheduledFuture<?> next;
    private volatile String secret = "";
    private volatile long attempt;

    public void listen(Consumer<State> listener) { this.listener = listener; listener.accept(state); }
    public State state() { return state; }

    // ── Start, poll, finish ──────────────────────────────────────────────────
    public void start()
    {
        if (!config.connect()) { publish(new State(State.Phase.FAILED, "", "", "Turn on Connect to ironcladrs.com in the plugin's settings first.")); return; }
        cancel(); long mine = ++attempt;
        publish(new State(State.Phase.STARTING, "", "", "Asking ironcladrs.com for a link code..."));
        post("/start", new JsonObject(), mine, result -> {
            String code = Json.text(result, "code"), url = Json.text(result, "url");
            secret = Json.text(result, "secret");
            if (code.isEmpty() || secret.isEmpty() || !url.startsWith("https://ironcladrs.com/"))
            { fail(mine, Json.text(result, "message").isEmpty() ? "Couldn't start linking. Try again in a minute." : Json.text(result, "message")); return; }
            publish(new State(State.Phase.WAITING, code, url, "Approve this code on the page that just opened in your browser."));
            schedulePoll(mine, Json.bounded(result, "pollEvery", 3, 2, 30));
        });
    }
    private void schedulePoll(long mine, int seconds)
    {
        if (mine != attempt) { return; }
        next = work.schedule(() -> poll(mine, seconds), seconds);
    }
    private void poll(long mine, int seconds)
    {
        State now = state; if (mine != attempt || now.phase != State.Phase.WAITING) { return; }
        post("/poll", Json.obj("code", now.code, "secret", secret), mine, result -> {
            String status = Json.text(result, "status"), key = Json.text(result, "key");
            if ("approved".equals(status) && key.matches("ice_[A-Za-z0-9_-]{43}"))
            {
                secret = "";
                // Saving the key fires ConfigChanged, which reconnects with it.
                clientThread.invoke(() -> configManager.setConfiguration(IroncladEventsConfig.GROUP, "apiKey", key));
                publish(new State(State.Phase.LINKED, now.code, "", "Linked. Connecting to your account..."));
            }
            else if ("pending".equals(status)) { schedulePoll(mine, seconds); }
            else { fail(mine, "That code expired. Press Link my account to get a new one."); }
        });
    }
    public void cancel()
    {
        attempt++; secret = "";
        ScheduledFuture<?> pending = next; if (pending != null) { pending.cancel(false); next = null; }
        calls.forEach(Call::cancel); calls.clear();
        if (state.phase != State.Phase.IDLE) { publish(State.IDLE_STATE); }
    }

    // ── Plumbing ─────────────────────────────────────────────────────────────
    private void fail(long mine, String message)
    { if (mine == attempt) { secret = ""; publish(new State(State.Phase.FAILED, "", "", message)); } }
    private void publish(State next) { state = next; listener.accept(next); }
    private void post(String path, JsonObject body, long mine, Consumer<JsonObject> success)
    {
        OkHttpClient transport = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
        Request request = new Request.Builder().url(BASE_URL + path).post(RequestBody.create(JSON, gson.toJson(body))).build();
        Call call = transport.newCall(request); calls.add(call);
        call.enqueue(new Callback()
        {
            @Override public void onFailure(Call failed, IOException ex)
            { calls.remove(failed); if (!failed.isCanceled()) { fail(mine, "Couldn't reach ironcladrs.com. Check your connection and try again."); } }
            @Override public void onResponse(Call finished, Response response)
            {
                calls.remove(finished);
                try (Response closeable = response)
                {
                    if (finished.isCanceled() || mine != attempt) { return; }
                    JsonObject result = new JsonObject();
                    if (response.body() != null)
                    {
                        okio.BufferedSource source = response.body().source(); source.request(MAX_RESPONSE_BYTES + 1L);
                        if (source.buffer().size() > MAX_RESPONSE_BYTES) { throw new IOException("Response too large"); }
                        String text = source.readUtf8(); if (!text.isEmpty()) { JsonObject parsed = gson.fromJson(text, JsonObject.class); if (parsed != null) { result = parsed; } }
                    }
                    if (response.code() == 429) { fail(mine, "Too many link attempts. Wait a few minutes, then try again."); return; }
                    if (response.code() >= 400) { fail(mine, Json.text(result, "message").isEmpty() ? "Linking failed (" + response.code() + "). Try again." : Json.text(result, "message")); return; }
                    success.accept(result);
                }
                catch (Exception ex) { log.debug("Link response unreadable", ex); fail(mine, "The site returned an unreadable answer. Try again."); }
            }
        });
    }
}

package com.ironcladrs.events.sync;

import com.google.gson.JsonObject;
import com.ironcladrs.events.api.dto.Json;

/** Additive fields are safe; unfamiliar view contracts retain only a site handoff. */
public final class EventView
{
    public static final int VERSION = 1;
    private EventView() {}
    public static boolean supported(JsonObject event)
    {
        if (!event.has("view")) { return true; } // Existing v1 servers predate the envelope.
        JsonObject view = Json.object(event, "view");
        return currentVersion(view) && "standard".equals(Json.text(view, "mode"));
    }
    private static boolean currentVersion(JsonObject view)
    {
        return view.has("version") && view.get("version").isJsonPrimitive()
            && view.getAsJsonPrimitive("version").isNumber() && Integer.toString(VERSION).equals(Json.text(view, "version"));
    }
    public static String message(JsonObject event)
    {
        JsonObject view = Json.object(event, "view");
        if (currentVersion(view) && "generic".equals(Json.text(view, "mode")))
        {
            String message = Json.text(view, "message");
            if (!message.isEmpty()) { return message; }
        }
        return "Open this event on the website for its instructions and progress. Automatic event reporting is paused for this view.";
    }
}

package com.ironcladrs.events.sync;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import java.time.Instant;

/** Copy-on-publication snapshot; consumers cannot mutate a running session. */
public final class SessionState
{
    public final boolean linked;
    public final String message;
    public final Instant syncedAt;
    private final JsonObject hello;
    private final JsonObject sync;
    public SessionState(boolean linked, String message, Instant syncedAt, JsonObject hello, JsonObject sync)
    {
        this.linked = linked; this.message = message; this.syncedAt = syncedAt;
        this.hello = hello.deepCopy(); this.sync = capped(sync);
    }
    private static JsonObject capped(JsonObject source)
    {
        JsonObject copy = source.deepCopy(); cap(copy, "events", 30); cap(copy, "claims", 25); cap(copy, "notices", 50); cap(copy, "pbLadders", 100);
        for (JsonElement value : Json.array(copy, "events"))
        {
            if (!value.isJsonObject()) { continue; } JsonObject event = value.getAsJsonObject();
            if (!EventView.supported(event))
            {
                for (String name : new String[]{"tasks", "prechecksOwed", "recommendations", "progress", "nextSteps"}) { event.add(name, new JsonArray()); }
                event.add("match", Json.obj("mode", "none")); event.add("metrics", new JsonObject()); event.add("priority", new JsonObject());
            }
            cap(event, "tasks", 300); cap(event, "links", 8); cap(event, "nextSteps", 3); cap(event, "prechecksOwed", 100);
            JsonObject priority = Json.object(event, "priority"); cap(priority, "targets", 10); if (event.has("priority")) { event.add("priority", priority); }
            cap(event, "recommendations", 50); cap(event, "standings", 5); cap(event, "progress", 100);
        }
        return copy;
    }
    private static void cap(JsonObject object, String name, int limit)
    {
        JsonArray values = Json.array(object, name); JsonArray limited = new JsonArray();
        for (int i = 0; i < Math.min(limit, values.size()); i++) { limited.add(values.get(i)); } object.add(name, limited);
    }
    public static SessionState empty(String message)
    { return new SessionState(false, message, null, new JsonObject(), new JsonObject()); }
    public JsonObject hello() { return hello.deepCopy(); }
    public JsonObject sync() { return sync.deepCopy(); }
    public boolean feature(String name) { return linked && Json.flag(Json.object(hello, "features"), name); }
    public int limit(String name, int fallback, int min, int max)
    { return Json.bounded(Json.object(hello, "limits"), name, fallback, min, max); }
    public String clanName() { return Json.text(hello, "clanName"); }
    public JsonArray events() { return Json.array(sync, "events").deepCopy(); }
    public static boolean inWindow(JsonObject event, Instant at)
    {
        Instant start = Json.time(Json.text(event, "startsAt")); Instant end = Json.time(Json.text(event, "endsAt"));
        return EventView.supported(event) && "live".equals(Json.text(event, "state")) && start != null && end != null && !at.isBefore(start) && at.isBefore(end);
    }
    public boolean hasLiveEvent(Instant at)
    { for (JsonElement event : events()) { if (event.isJsonObject() && inWindow(event.getAsJsonObject(), at)) { return true; } } return false; }
}

package com.ironcladrs.events.sync;

import com.google.gson.*;
import com.ironcladrs.events.*;
import com.ironcladrs.events.api.ApiClient;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.notice.ChatNotices;
import java.time.Instant;
import java.util.UUID;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Hello binds a session before any uploads. Stale callbacks cannot publish into a new account. */
@Singleton
public class SyncService
{
    @Inject private PlayerGuard guard;
    @Inject private IroncladEventsConfig config;
    @Inject private ApiClient api;
    @Inject private ChatNotices notices;
    @Inject private com.ironcladrs.events.filters.RarityTable rarity;
    private SessionState state = SessionState.empty("Connect in settings to get started.");
    private Consumer<SessionState> listener = ignored -> {};
    private boolean busy, blocked;
    private long generation = -1;
    private Instant next = Instant.EPOCH, lastManual = Instant.EPOCH, lastRead = Instant.EPOCH;
    private int failures;
    private String cursor = "", etag = "";

    public SessionState state() { return state; }
    public boolean current() { return state.linked && generation == guard.generation(); }
    public void listen(Consumer<SessionState> listener) { this.listener = listener; listener.accept(state); }
    public void reset()
    {
        generation = guard.generation(); busy = false; blocked = false; failures = 0;
        cursor = ""; etag = ""; next = Instant.EPOCH; lastRead = Instant.EPOCH;
        notices.reset();
        publish(SessionState.empty(!config.connect() ? "Connect in settings to get started."
            : guard.identity() == null ? "Log in on a standard world with a valid plugin key." : "Connecting…"));
    }
    public void tick(Instant now)
    {
        guard.refresh();
        if (generation != guard.generation()) { reset(); }
        if (guard.identity() == null || blocked || busy || now.isBefore(next)) { return; }
        if (!state.linked) { hello(now); } else { sync(now); }
    }
    public void manual(Instant now)
    {
        if (now.isBefore(lastManual.plusSeconds(10)) || now.isBefore(lastRead.plusSeconds(20))) { return; }
        lastManual = now; next = now; tick(now);
    }
    private void hello(Instant now)
    {
        JsonObject switches = Json.obj("connect", config.connect());
        for (String key : IroncladEventsConfig.UPLOAD_KEYS) { switches.addProperty(key, IroncladEventsConfig.upload(config, key)); }
        JsonObject payload = Json.obj("pluginVersion", ApiClient.VERSION, "switches", switches, "idempotencyKey", UUID.randomUUID());
        long expected = generation; busy = true;
        api.request(guard.identity(), "POST", "/hello", payload, null, null, result -> {
            if (expected != guard.generation()) { return; } busy = false;
            if (!result.success()) { failure(result, now); return; }
            if (compareVersions(ApiClient.VERSION, Json.text(result.data, "minVersion")) < 0)
            { blocked = true; publish(SessionState.empty("Update Ironclad Events to connect.")); return; }
            failures = 0; next = Instant.EPOCH;
            JsonObject hello = result.data.deepCopy(); rarity.update(Json.object(hello, "rarity")); hello.remove("rarity");
            publish(new SessionState(true, "Connected", null, hello, new JsonObject()));
            tick(Instant.now());
        });
    }
    private void sync(Instant now)
    {
        long expected = generation; busy = true; lastRead = now;
        api.request(guard.identity(), "GET", "/sync", Json.obj("since", cursor), null, etag, result -> {
            if (expected != guard.generation()) { return; } busy = false;
            if (result.status == 304)
            {
                failures = 0; next = Instant.now().plusSeconds(interval(Instant.now()));
                publish(new SessionState(true, "Connected", Instant.now(), state.hello(), state.sync())); return;
            }
            if (!result.success()) { failure(result, Instant.now()); return; }
            failures = 0;
            cursor = Json.text(result.data, "cursor"); etag = result.etag.isEmpty() ? Json.text(result.data, "etag") : result.etag;
            if (!etag.matches("[\\x20-\\x7E]{0,200}")) { etag = ""; }
            JsonObject hello = state.hello();
            if (result.data.has("features")) { hello.add("features", Json.object(result.data, "features")); }
            publish(new SessionState(true, "Connected", Instant.now(), hello, result.data));
            notices.accept(Json.array(result.data, "notices"));
            next = Instant.now().plusSeconds(interval(Instant.now()));
        });
    }
    private void failure(ApiClient.Result result, Instant now)
    {
        failures++;
        next = now.plusSeconds(Math.max(result.status == 429 ? result.retryAfter() : 0, backoff(failures)));
        if (!result.retryable()) { blocked = true; }
        boolean linked = state.linked && result.retryable();
        publish(new SessionState(linked, result.message(), state.syncedAt, state.hello(), state.sync()));
    }
    private int interval(Instant now)
    {
        boolean active = state.hasLiveEvent(now);
        for (JsonElement value : state.events())
        {
            if (!value.isJsonObject()) { continue; }
            Instant start = Json.time(Json.text(value.getAsJsonObject(), "startsAt"));
            if (start != null && start.isAfter(now) && !start.isAfter(now.plusSeconds(3600))) { active = true; }
        }
        return Json.bounded(Json.object(state.hello(), "poll"), active ? "liveSec" : "idleSec", active ? 60 : 600, 20, 3600);
    }
    public static int backoff(int failures) { return Math.min(600, 20 * (1 << Math.min(5, Math.max(0, failures - 1)))); }
    public static int compareVersions(String left, String right)
    {
        if (!right.matches("[0-9]+(?:\\.[0-9]+){0,3}")) { return right.isEmpty() ? 0 : -1; }
        String[] a = left.split("\\."), b = right.split("\\.");
        try { for (int i = 0; i < Math.max(a.length, b.length); i++)
        { int cmp = Integer.compare(i < a.length ? Integer.parseInt(a[i]) : 0, i < b.length ? Integer.parseInt(b[i]) : 0); if (cmp != 0) { return cmp; } } }
        catch (NumberFormatException ex) { return -1; }
        return 0;
    }
    private void publish(SessionState nextState) { state = nextState; listener.accept(nextState); }
}

