package com.ironcladrs.events.ui;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import java.awt.*;
import javax.swing.*;

/** Each claim leads with its status word; the colour only repeats what the word says. */
public final class ClaimsList extends JPanel
{
    public ClaimsList(JsonArray claims, long eventId, int cap)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS)); setOpaque(false); setAlignmentX(Component.LEFT_ALIGNMENT); int count = 0;
        for (JsonElement value : claims)
        {
            if (!value.isJsonObject()) { continue; } JsonObject claim = value.getAsJsonObject();
            if (eventId >= 0 && Json.number(claim, "eventId", -1) != eventId) { continue; } if (++count > cap) { break; }
            String status = Json.text(claim, "status"), item = Json.text(claim, "item"), label = Json.text(claim, "label");
            JPanel row = new JPanel(new BorderLayout(6, 0)); row.setOpaque(false); row.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
            JLabel what = Ui.name(item.isEmpty() ? label : item); what.setForeground(Color.WHITE);
            row.add(what, BorderLayout.CENTER); row.add(Ui.status(status), BorderLayout.EAST); add(Ui.fit(row));
            if (!item.isEmpty() && !label.isEmpty()) { add(Ui.muted(label, Ui.WIDTH)); }
            if (claim.has("killCount") && !claim.get("killCount").isJsonNull()) { add(Ui.muted("Drop at KC " + Json.number(claim, "killCount", 0), Ui.WIDTH)); }
            if (status.equals("denied") && !Json.text(claim, "reason").isEmpty()) { add(Ui.muted("Reason: " + Json.text(claim, "reason"), Ui.WIDTH)); }
        }
        if (count == 0) { add(Ui.muted("No claims yet. Drops you file show up here with their status.", Ui.WIDTH)); }
    }
}

package com.ironcladrs.events.ui;

import com.google.gson.*;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.sync.SessionState;
import java.util.ArrayList;
import java.util.List;
import javax.swing.*;

/**
 * Clan defaults in one press: the clan's loot filters plus every upload the clan recommends, after one
 * confirmation that names each switch and carries RuneLite's third-party warning. Only known upload keys
 * are ever switched on, never anything else the server sends, and nothing is switched off.
 */
public final class ClanSettingsCard extends JPanel
{
    public ClanSettingsCard(IroncladEventsConfig config, SessionState state, IroncladPanel.Actions actions)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS)); setAlignmentX(LEFT_ALIGNMENT);
        setBackground(net.runelite.client.ui.ColorScheme.DARKER_GRAY_COLOR); setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 8));
        JsonObject preset = Json.object(state.sync(), "clanPreset");
        if (preset.size() == 0) { preset = Json.object(state.hello(), "clanPreset"); }
        final JsonObject snapshot = preset.deepCopy();
        Ui.heading(this, "Clan defaults");
        if (Json.number(preset, "version", 0) != 1)
        {
            add(Ui.text("Connect to see what the clan recommends. Your own settings are in use.", Ui.CARD_WIDTH));
            if (config.useClanSettings()) { add(Ui.fit(Ui.button("Use personal settings", () -> actions.clanSettings(false)))); }
            return;
        }
        List<Integer> missing = missing(config, snapshot);
        if (config.useClanSettings() && missing.isEmpty())
        {
            JLabel on = Ui.text("On: clan loot filters and every upload the clan recommends.", Ui.CARD_WIDTH); on.setForeground(Ui.GOOD); add(on);
        }
        else
        {
            add(Ui.text(missing.isEmpty() ? "Use the clan's loot filters. Your uploads already match what the clan recommends. You confirm once."
                : "Turn on what the clan recommends in one go: " + missing.size() + " upload" + (missing.size() == 1 ? "" : "s") + " and the clan's loot filters. You confirm once.", Ui.CARD_WIDTH));
            add(Ui.fit(Ui.primary("Use clan defaults", () -> enable(this, config, snapshot, actions))));
        }
        add(Ui.fit(Ui.button("See the clan's settings", () -> JOptionPane.showMessageDialog(this, scroll(preview(snapshot)), "Clan defaults", JOptionPane.INFORMATION_MESSAGE))));
        if (config.useClanSettings()) { add(Ui.fit(Ui.button("Use personal settings", () -> actions.clanSettings(false)))); }
        add(Ui.muted("Personal settings put your own loot filters back. Uploads stay as they are; turn any off in the plugin's settings.", Ui.CARD_WIDTH));
    }
    /** Are the clan defaults offered but not fully on? Drives the button at the top of the panel. */
    public static boolean offered(IroncladEventsConfig config, SessionState state)
    {
        JsonObject preset = preset(state);
        return Json.number(preset, "version", 0) == 1 && (!config.useClanSettings() || !missing(config, preset).isEmpty());
    }
    /** The one confirmation (names each switch, carries the third-party warning), then turns them on. */
    public static void enable(java.awt.Component parent, IroncladEventsConfig config, JsonObject preset, IroncladPanel.Actions actions)
    {
        List<Integer> missing = missing(config, preset);
        if (JOptionPane.showOptionDialog(parent, scroll(confirmText(config, preset)), "Use clan defaults?", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE,
            null, new String[]{"Use clan defaults", "Cancel"}, "Cancel") == JOptionPane.YES_OPTION)
        {
            List<String> keys = new ArrayList<>(); for (int i : missing) { keys.add(IroncladEventsConfig.UPLOAD_KEYS[i]); }
            actions.clanDefaults(keys);
        }
    }
    public static JsonObject preset(SessionState state)
    {
        JsonObject preset = Json.object(state.sync(), "clanPreset");
        return (preset.size() == 0 ? Json.object(state.hello(), "clanPreset") : preset).deepCopy();
    }
    /** Positions in UPLOAD_KEYS the clan recommends that are still off. */
    public static List<Integer> missing(IroncladEventsConfig config, JsonObject preset)
    {
        JsonObject recommended = Json.object(preset, "recommended"); List<Integer> result = new ArrayList<>();
        for (int i = 0; i < IroncladEventsConfig.UPLOAD_KEYS.length; i++)
        { String key = IroncladEventsConfig.UPLOAD_KEYS[i]; if (Json.flag(recommended, key) && !IroncladEventsConfig.upload(config, key)) { result.add(i); } }
        return result;
    }
    public static String confirmText(IroncladEventsConfig config, JsonObject preset)
    {
        StringBuilder text = new StringBuilder(IroncladEventsConfig.THIRD_PARTY_WARNING).append(".\n\nThis turns on:\n");
        for (int i : missing(config, preset)) { text.append("- ").append(IroncladEventsConfig.UPLOAD_LABELS[i]).append('\n'); }
        text.append("- The clan's loot filters (your own are kept for later)\n\nNothing is turned off. Screenshots include your whole game window and chat.")
            .append(" Hover each setting in RuneLite's settings to see exactly what it sends, and turn any off there.");
        return text.toString();
    }
    private static String preview(JsonObject preset)
    {
        JsonObject filters = Json.object(preset, "filters"), recommended = Json.object(preset, "recommended");
        // Every filter the clan sets, not just the first three (2026-11-27).
        StringBuilder text = new StringBuilder("Clan filters\n");
        for (java.util.Map.Entry<String, JsonElement> entry : filters.entrySet()) { text.append(filterLabel(entry.getKey())).append(": ").append(filterValue(entry.getKey(), entry.getValue())).append('\n'); }
        if (filters.size() == 0) { text.append("none set\n"); }
        text.append("\nRecommended uploads\n");
        for (int i = 0; i < IroncladEventsConfig.UPLOAD_KEYS.length; i++)
        { text.append(IroncladEventsConfig.UPLOAD_LABELS[i]).append(": ").append(Json.flag(recommended, IroncladEventsConfig.UPLOAD_KEYS[i]) ? "On" : "Off").append('\n'); }
        text.append("\nRevision ").append(Json.text(preset, "revision")).append(". Filters can stop an event drop from filing.");
        return text.toString();
    }
    private static String orNone(String value) { return value.trim().isEmpty() ? "none" : value; }
    private static final java.util.Map<String, String> FILTER_LABELS = new java.util.HashMap<>();
    static
    {
        String[][] labels = {{"minimumWallValue", "Wall of Fame minimum (gp, 0 = the site's minimum)"}, {"ignoredLootItems", "Never send these items"}, {"ignoredLootSources", "Never send from these"},
            {"alwaysSendItems", "Always send these items"}, {"screenshotMinValue", "Screenshot drops worth at least (gp)"}, {"sendClueLoot", "Send clue scroll loot"}, {"screenshotScale", "Screenshot size (%)"},
            {"relayBroadcasts", "Relay clan broadcasts"}, {"ignoredDeathRegions", "Ignore deaths in these regions"}, {"petDuplicates", "Announce duplicate pets"}, {"levelMinimum", "Lowest level announced"},
            {"levelInterval", "Announce every N levels"}, {"virtualLevels", "Announce virtual levels"}, {"totalLevelInterval", "Announce total level every"}, {"clueMinTier", "Lowest clue tier shared"},
            {"rarityOverride", "Rarity override (1 in X, 0 = off)"}, {"rarityAndValue", "Rare drops must also meet the minimum"}, {"sendPkLoot", "Send PK loot"}, {"ignoreSafeDeaths", "Ignore safe deaths"},
            {"safeDeathExceptions", "Safe deaths that still count"}, {"caMinTier", "Lowest combat task tier"}, {"diaryMinTier", "Lowest diary tier"}};
        for (String[] l : labels) { FILTER_LABELS.put(l[0], l[1]); }
    }
    private static String filterLabel(String key)
    {
        String known = FILTER_LABELS.get(key); if (known != null) { return known; }
        String words = key.replaceAll("([a-z])([A-Z])", "$1 $2").toLowerCase(java.util.Locale.ROOT);
        return words.isEmpty() ? key : Character.toUpperCase(words.charAt(0)) + words.substring(1);
    }
    private static String filterValue(String key, JsonElement value)
    {
        if (value == null || value.isJsonNull()) { return "none"; }
        if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean()) { return value.getAsBoolean() ? "On" : "Off"; }
        String text = value.isJsonPrimitive() ? value.getAsString() : value.toString();
        return orNone(text.replace('_', ' '));
    }
    private static JScrollPane scroll(String text)
    {
        JTextArea area = new JTextArea(text, 18, 32); area.setLineWrap(true); area.setWrapStyleWord(true); area.setEditable(false); area.setCaretPosition(0);
        return new JScrollPane(area);
    }
}

package com.ironcladrs.events.ui;

import com.google.gson.*;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.sync.EventView;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.awt.*;
import java.util.Set;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.game.ItemManager;

/**
 * Every event type is rendered from the member's revealed server view, with no local rule engine.
 * The event and the team are the two boxes (with their countdown and score bars); everything else is a
 * foldable section that only appears when the server sent something for it, so a quiet event stays short.
 * Redesigned 2026-11-27 (user: "the data presented in the plugin should be presented better").
 */
public final class EventCard extends JPanel
{
    private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("EEE MMM d, HH:mm").withZone(ZoneId.systemDefault());
    private static final Color[] MEDALS = {new Color(230, 172, 30), new Color(190, 196, 204), new Color(196, 128, 72)};

    public EventCard(JsonObject event, JsonArray claims, ItemManager items, IroncladPanel.Actions actions, PrecheckList prechecks, boolean captainAvailable, Set<String> closed)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS)); setOpaque(false); setAlignmentX(LEFT_ALIGNMENT);
        long id = Json.number(event, "id", -1); String key = "e" + id + ":";

        // ── The event: name, tags, countdown and how far through it is ──
        JPanel card = Ui.card(); add(card);
        card.add(Ui.bold(Json.text(event, "name"), Ui.CARD_WIDTH));
        Instant now = Instant.now(), start = Json.time(Json.text(event, "startsAt")), end = Json.time(Json.text(event, "endsAt"));
        boolean live = "live".equals(Json.text(event, "state")) && (start == null || !start.isAfter(now)) && (end == null || end.isAfter(now));
        String type = Json.text(event, "typeLabel");
        card.add(Ui.line(type.isEmpty() ? null : Ui.pill(type, Ui.MUTED), live ? Ui.pill("Live", Ui.GOOD) : end != null && !end.isAfter(now) ? Ui.pill("Ended", Ui.BAD) : Ui.pill("Upcoming", Ui.ACCENT)));
        Ui.gap(card, 6);
        if (start != null && start.isAfter(now))
        {
            card.add(big("Starts in " + Ui.span(Duration.between(now, start).toMinutes())));
            card.add(Ui.muted(WHEN.format(start), Ui.CARD_WIDTH));
        }
        else if (end != null)
        {
            card.add(big(end.isAfter(now) ? Ui.span(Duration.between(now, end).toMinutes()) + " left" : "Finished"));
            if (start != null && end.isAfter(start))
            { Ui.gap(card, 3); card.add(Ui.bar((double) Duration.between(start, now).toMinutes() / Duration.between(start, end).toMinutes(), Ui.GOLD)); Ui.gap(card, 3); }
            card.add(Ui.muted("Ends " + WHEN.format(end), Ui.CARD_WIDTH));
        }
        Ui.gap(card, 6); Ui.link(card, "Open event on site", Json.text(event, "url"));
        if (!EventView.supported(event)) { Ui.gap(card, 4); card.add(Ui.text(EventView.message(event), Ui.CARD_WIDTH)); return; }

        // ── Prechecks: something to do now, so straight under the event, above team and standings ──
        int owed = Json.array(event, "prechecksOwed").size();
        if (owed > 0 && prechecks != null) { Ui.section(this, key + "prechecks", "Prechecks owed", Integer.toString(owed), closed).add(prechecks); }

        // ── Domination: territories one step from taking or losing (server: pluginAreas.js) ──
        JsonArray closeCalls = Json.array(event, "closeCalls");
        if (closeCalls.size() > 0)
        {
            JPanel body = Ui.section(this, key + "close", "Close calls", Integer.toString(closeCalls.size()), closed);
            for (JsonElement value : closeCalls)
            {
                if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject(); boolean risk = "risk".equals(Json.text(row, "kind"));
                body.add(Ui.line(Ui.pill(risk ? "At risk" : "Within reach", risk ? Ui.BAD : Ui.GOOD), Ui.bold(Json.text(row, "name"), Ui.CARD_WIDTH - 80)));
                body.add(Ui.muted(Json.text(row, "text"), Ui.WIDTH));
                String accepts = Json.text(row, "accepts");
                if (!accepts.isEmpty()) { body.add(Ui.muted("Counts: " + accepts, Ui.WIDTH)); }
                Ui.gap(body, 4);
            }
        }

        // ── Battleship Bingo: the enemy fleet, updated as your team sinks ships and finds buoys ──
        JsonObject fleet = Json.object(event, "fleet");
        if (fleet.size() > 0) { fleet(fleet, key, closed); }

        // ── Your team: rank and score, with a bar when the score is "x of y" ──
        JsonObject team = Json.object(event, "team");
        if (team.size() > 0)
        {
            JPanel box = Ui.card(); Ui.gap(this, 6); add(box);
            long rank = Json.number(team, "rank", 0), of = Json.number(team, "of", 0);
            JPanel top = new JPanel(new BorderLayout(6, 0)); top.setOpaque(false);
            JLabel name = Ui.name(Json.text(team, "name")); name.setFont(FontManager.getRunescapeBoldFont()); name.setForeground(Color.WHITE);
            top.add(name, BorderLayout.CENTER);
            if (rank > 0) { top.add(Ui.pill("#" + rank + " of " + of, rank <= 3 ? MEDALS[(int) rank - 1] : Ui.MUTED), BorderLayout.EAST); }
            box.add(Ui.muted("Your team", Ui.CARD_WIDTH)); box.add(Ui.fit(top));
            String score = Json.text(team, "scoreText");
            if (!score.isEmpty())
            {
                Ui.gap(box, 4); box.add(Ui.row("Score", score, false));
                double f = Ui.fraction(score); if (!Double.isNaN(f)) { Ui.gap(box, 2); box.add(Ui.bar(f, Ui.GOOD)); }
            }
        }

        // ── What to do now: the team's strategy page ──
        // Only the captain's plan goes here (user, 2026-11-20): their message, priority tasks with progress,
        // and recommendations for you or the whole team. Solo events have no team plan, so no section.
        JsonObject priority = Json.object(event, "priority"); JsonArray steps = Json.array(event, "nextSteps"), recommendations = Json.array(event, "recommendations");
        boolean planned = !Json.text(priority, "text").isEmpty() || steps.size() > 0 || recommendations.size() > 0;
        if (planned || team.size() > 0)
        {
            JPanel body = Ui.section(this, key + "now", "What to do now", recommendations.size() > 0 ? recommendations.size() + " ask" + (recommendations.size() == 1 ? "" : "s") : null, closed);
            if (!planned)
            {
                body.add(Ui.muted("Your captain hasn't set a plan yet. It shows here as soon as they save one on the team page.", Ui.WIDTH));
                for (JsonElement value : Json.array(event, "links"))
                { if (value.isJsonObject() && "My team".equals(Json.text(value.getAsJsonObject(), "label"))) { Ui.link(body, "Open team page", Json.text(value.getAsJsonObject(), "url")); } }
            }
            String message = Json.text(priority, "text");
            if (!message.isEmpty())
            {
                JPanel quote = Ui.column(); quote.setBackground(ColorScheme.DARKER_GRAY_COLOR);
                quote.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 3, 0, 0, Ui.GOLD), BorderFactory.createEmptyBorder(5, 7, 5, 6)));
                JLabel from = Ui.muted("From your captain", Ui.BESIDE_ICON + 20); from.setForeground(Ui.GOLD); quote.add(from); quote.add(Ui.text(message, Ui.BESIDE_ICON + 20));
                body.add(Ui.fit(quote)); Ui.gap(body, 4);
            }
            int count = 0;
            for (JsonElement value : steps)
            {
                if (++count > 3) { break; } if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject();
                boolean done = Json.flag(row, "done");
                JLabel line = Ui.text((done ? "Done: " : "") + Json.text(row, "text"), Ui.WIDTH - 18); line.setIcon(new Ui.StateDot(done)); line.setIconTextGap(6);
                if (done) { line.setForeground(Ui.MUTED); }
                body.add(line);
            }
            int shown = 0;
            for (JsonElement value : recommendations)
            {
                if (++shown > 50) { break; } if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject(); long recommendation = Json.number(row, "id", -1);
                JPanel ask = Ui.card(); Ui.gap(body, 6); body.add(ask);
                JLabel title = Ui.muted("Captain's ask", Ui.CARD_WIDTH); title.setForeground(Ui.GOLD); ask.add(title); ask.add(Ui.text(Json.text(row, "text"), Ui.CARD_WIDTH));
                String response = Json.text(row, "response"); if (!response.isEmpty()) { ask.add(Ui.muted("Your answer: " + response.replace('_', ' '), Ui.CARD_WIDTH)); }
                Ui.gap(ask, 4);
                if (captainAvailable)
                {
                    ask.add(Ui.buttons(Ui.button("On it", () -> actions.respond(recommendation, "on_it")),
                        Ui.button("Done", () -> actions.respond(recommendation, "done")), Ui.button("Can't", () -> actions.respond(recommendation, "cant"))));
                }
                else { ask.add(Ui.muted("Answer this on the site for now.", Ui.CARD_WIDTH)); }
            }
        }

        // ── Domination: who holds each region and its kingdom bonus ──
        JsonArray areas = Json.array(event, "areas");
        if (areas.size() > 0)
        {
            int ours = 0; for (JsonElement value : areas) { if (value.isJsonObject() && "yours".equals(Json.text(value.getAsJsonObject(), "status"))) { ours++; } }
            JPanel body = Ui.section(this, key + "areas", "Regions", ours + " of " + areas.size() + " yours", closed);
            for (JsonElement value : areas)
            {
                if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject(); String status = Json.text(row, "status");
                body.add(Ui.line(Ui.pill("yours".equals(status) ? "Yours" : "theirs".equals(status) ? "Theirs" : "Open", "yours".equals(status) ? Ui.GOOD : "theirs".equals(status) ? Ui.BAD : Ui.MUTED),
                    Ui.bold(Json.text(row, "name"), Ui.CARD_WIDTH - 60)));
                body.add(Ui.muted(Json.text(row, "text"), Ui.WIDTH)); Ui.gap(body, 4);
            }
        }

        // ── Standings: medal colours for the top three, your team highlighted ──
        JsonArray standings = Json.array(event, "standings");
        if (standings.size() > 0)
        {
            JPanel body = Ui.section(this, key + "standings", "Standings", null, closed); int rank = 0;
            for (JsonElement value : standings)
            {
                if (++rank > 5) { break; } if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject();
                body.add(standing(rank, Json.text(row, "name"), Json.text(row, "scoreText"), Json.flag(row, "mine")));
            }
        }

        // ── Tasks ──
        JsonArray tasks = Json.array(event, "tasks");
        if (tasks.size() > 0)
        {
            int done = 0; for (JsonElement task : tasks) { if (task.isJsonObject() && Json.flag(task.getAsJsonObject(), "done")) { done++; } }
            JPanel body = Ui.section(this, key + "tasks", "Tasks", done + " of " + tasks.size() + " done", closed);
            body.add(Ui.bar((double) done / tasks.size(), Ui.GOOD)); Ui.gap(body, 6);
            body.add(new TaskList(tasks, items));
        }

        // ── Live progress (only when there is some) ──
        JsonArray progressRows = Json.array(event, "progress");
        if (progressRows.size() > 0)
        {
            JPanel progress = Ui.section(this, key + "progress", "Live progress", null, closed); int rows = 0;
            for (JsonElement value : progressRows)
            {
                if (++rows > 100) { break; } if (!value.isJsonObject()) { continue; } JsonObject row = value.getAsJsonObject();
                progress.add(Ui.row(Json.text(row, "label"), Json.text(row, "confirmedText"), false));
                String provisional = Json.text(row, "provisionalText");
                if (!provisional.isEmpty()) { progress.add(Ui.muted("+ " + provisional + " waiting for Wise Old Man", Ui.WIDTH)); }
            }
        }

        // ── Links: two to a row ──
        JsonArray links = Json.array(event, "links");
        if (links.size() > 0)
        {
            JPanel body = Ui.section(this, key + "links", "On the site", null, closed);
            JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4)); grid.setOpaque(false); int count = 0;
            for (JsonElement value : links)
            {
                if (++count > 8 || !value.isJsonObject()) { continue; } JsonObject link = value.getAsJsonObject(); String url = Json.text(link, "url");
                if (Ui.allowedLink(url)) { grid.add(Ui.button(Json.text(link, "label"), () -> net.runelite.client.util.LinkBrowser.browse(url))); }
            }
            body.add(Ui.fit(grid));
        }
    }

    private static JLabel big(String text)
    { JLabel label = new JLabel(Ui.plain(text)); label.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f)); label.setForeground(Color.WHITE); label.setAlignmentX(LEFT_ALIGNMENT); return label; }

    /** One standings line: a medal-coloured rank, the team, its score; your team on a lighter band. */
    private static JPanel standing(int rank, String name, String score, boolean mine)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0)); row.setOpaque(mine); row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
        JLabel place = new JLabel(Integer.toString(rank)); place.setFont(FontManager.getRunescapeBoldFont()); place.setPreferredSize(new Dimension(14, 14));
        place.setForeground(rank <= 3 ? MEDALS[rank - 1] : Ui.MUTED);
        JLabel team = Ui.name(name + (mine ? " (you)" : "")); team.setForeground(mine ? Color.WHITE : Ui.TEXT); if (mine) { team.setFont(FontManager.getRunescapeBoldFont()); }
        JLabel value = new JLabel(Ui.plain(score)); value.setForeground(mine ? Color.WHITE : Ui.MUTED); value.setFont(FontManager.getRunescapeSmallFont());
        row.add(place, BorderLayout.WEST); row.add(team, BorderLayout.CENTER); row.add(value, BorderLayout.EAST); return Ui.fit(row);
    }

    /** Enemy ship types (sunk or afloat), buoys found of each type, your shots and your own fleet. */
    private void fleet(JsonObject fleet, String key, Set<String> closed)
    {
        JsonArray ships = Json.array(fleet, "ships"); int sunk = 0;
        for (JsonElement value : ships) { if (value.isJsonObject() && Json.flag(value.getAsJsonObject(), "sunk")) { sunk++; } }
        String enemy = Json.text(fleet, "enemyName");
        JPanel body = Ui.section(this, key + "fleet", "Enemy fleet" + (enemy.isEmpty() ? "" : ": " + enemy), sunk + " of " + ships.size() + " sunk", closed);
        for (JsonElement value : ships)
        {
            if (!value.isJsonObject()) { continue; } JsonObject ship = value.getAsJsonObject(); boolean down = Json.flag(ship, "sunk");
            body.add(Ui.line(Ui.pill(down ? "Sunk" : "Afloat", down ? Ui.GOOD : Ui.MUTED), Ui.text(Json.text(ship, "label") + " (" + Json.number(ship, "length", 0) + ")", Ui.CARD_WIDTH - 60)));
        }
        JsonArray buoys = Json.array(fleet, "buoys");
        if (buoys.size() > 0)
        {
            Ui.gap(body, 4); JLabel title = Ui.muted("Buoys found", Ui.WIDTH); title.setForeground(Ui.GOLD); body.add(title);
            for (JsonElement value : buoys)
            {
                if (!value.isJsonObject()) { continue; } JsonObject buoy = value.getAsJsonObject();
                body.add(Ui.row(Json.text(buoy, "label"), Json.number(buoy, "found", 0) + " of " + Json.number(buoy, "total", 0), false));
            }
        }
        JsonObject shots = Json.object(fleet, "shots"), mine = Json.object(fleet, "yourFleet");
        Ui.gap(body, 4);
        body.add(Ui.row("Your shots", Json.number(shots, "hits", 0) + " hit, " + Json.number(shots, "misses", 0) + " miss", false));
        if (Json.number(mine, "total", 0) > 0) { body.add(Ui.row("Your fleet", Json.number(mine, "afloat", 0) + " of " + Json.number(mine, "total", 0) + " afloat", false)); }
    }
}

package com.ironcladrs.events.ui;

import com.google.gson.*;
import com.ironcladrs.events.IroncladEventsConfig;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.sync.AccountLinker;
import com.ironcladrs.events.sync.SessionState;
import java.awt.*;
import java.util.*;
import java.util.function.Consumer;
import javax.swing.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

/** The EDT renders only immutable snapshots; actions return through the client-thread dispatcher. */
public final class IroncladPanel extends PluginPanel
{
    public interface Actions
    {
        void sync(); void bank(long event, long precheck, boolean automatic); void dismissBank(long event, long precheck);
        void capture(Consumer<byte[]> preview); void picture(long event, long precheck, String value, String note, byte[] bytes);
        void respond(long id, String response);
        default void clanSettings(boolean enabled) {}
        /** Switch on these upload keys plus the clan's loot filters; the plugin re-checks every key. */
        default void clanDefaults(java.util.List<String> keys) {}
        default void link() {}
        default void cancelLink() {}
    }
    private final IroncladEventsConfig config;
    private final ItemManager items;
    private Actions actions;
    private final JPanel content = Ui.column();
    private final javax.swing.Timer timer;
    private StatusFooter footer;
    private long selected = -1;
    private SessionState state = SessionState.empty("Connect in settings to get started.");
    private Map<String, JsonObject> bank = Collections.emptyMap();
    private int unsent;
    private String status = "";
    private boolean showSetup;
    private final JPanel bankContent = Ui.column();
    private final JLabel statusLabel = Ui.text("");
    private final Map<Long, PrecheckList> precheckViews = new HashMap<>();
    private final Map<Long, JsonArray> precheckSchemas = new HashMap<>();
    /** Sections the member folded shut; kept across syncs so a re-render never reopens them. */
    private final Set<String> closed = new HashSet<>();
    private final Icon logo = loadLogo();
    private AccountLinker.State link = AccountLinker.State.IDLE_STATE;
    /** Which tab is open: the event, or the member's own claims. */
    private String tab = "event";
    public IroncladPanel(IroncladEventsConfig config, ItemManager items, Actions actions)
    {
        super(true); this.config = config; this.items = items; this.actions = actions;
        setLayout(new BorderLayout()); setBackground(net.runelite.client.ui.ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8)); add(content, BorderLayout.NORTH);
        getScrollPane().getVerticalScrollBar().setUnitIncrement(16);
        timer = new javax.swing.Timer(1000, event -> { if (footer != null) { footer.update(); } }); timer.start();
    }
    public void stop() { timer.stop(); closed.clear(); bank = Collections.emptyMap(); precheckViews.clear(); precheckSchemas.clear(); bankContent.removeAll(); content.removeAll(); }
    public void update(SessionState state, int unsent, Actions actions)
    {
        if (this.state.feature("prechecks") != state.feature("prechecks") || this.state.feature("bankPrechecks") != state.feature("bankPrechecks"))
        { precheckViews.clear(); precheckSchemas.clear(); }
        boolean changed = this.state.linked != state.linked || !this.state.message.equals(state.message)
            || !this.state.sync().equals(state.sync()) || !this.state.hello().equals(state.hello());
        this.state = state; this.unsent = unsent; this.actions = actions;
        if (changed) { render(); } else if (footer != null) { footer.state(state); footer.unsent(unsent); }
    }
    /** Linking progress comes from the linker; a change redraws the setup view. */
    public void link(AccountLinker.State state)
    {
        if (state == null || state == link) { return; }
        boolean fresh = state.phase == AccountLinker.State.Phase.WAITING && !(link.phase == AccountLinker.State.Phase.WAITING && link.code.equals(state.code));
        link = state; render();
        // Open the approve page once per new code, and only ever on the clan site.
        if (fresh && Ui.allowedLink(state.url)) { net.runelite.client.util.LinkBrowser.browse(state.url); }
    }
    public void bank(Map<String, JsonObject> cards) { bank = cards; renderBank(); }
    public void unsent(int count) { unsent = count; if (footer != null) { footer.unsent(count); } }
    public void status(String text, int unsent)
    { status = text; statusLabel.setText("<html><body style='width:" + Ui.css(Ui.WIDTH) + "px'>" + Ui.html(text) + "</body></html>"); unsent(unsent); }
    private void renderBank()
    {
        bankContent.removeAll(); if (state.linked) { for (JsonObject card : bank.values()) { Ui.gap(bankContent, 6); bankContent.add(new BankSendCard(card, items, actions)); } }
        bankContent.revalidate(); bankContent.repaint();
    }
    private static Icon loadLogo()
    {
        try { return new ImageIcon(ImageUtil.loadImageResource(IroncladPanel.class, "/com/ironcladrs/events/logo.png")); }
        catch (RuntimeException ex) { return null; }
    }
    private JPanel header()
    {
        JPanel header = new JPanel(new BorderLayout(8, 0)); header.setOpaque(false);
        if (logo != null) { header.add(new JLabel(logo), BorderLayout.WEST); }
        JPanel words = Ui.column(); words.setOpaque(false);
        JLabel title = new JLabel("Ironclad Events"); title.setFont(FontManager.getRunescapeBoldFont()); title.setForeground(Color.WHITE);
        words.add(Box.createVerticalGlue()); words.add(title);
        String clan = state.clanName();
        words.add(Ui.line(state.linked ? Ui.pill("Connected", Ui.GOOD) : Ui.pill("Not connected", Ui.MUTED), clan.isEmpty() ? null : Ui.pill(clan, Ui.GOLD)));
        words.add(Box.createVerticalGlue());
        header.add(words, BorderLayout.CENTER);
        // Sync is reachable at the top as well as in the footer of a long list.
        JPanel right = new JPanel(new GridBagLayout()); right.setOpaque(false); JButton sync = Ui.button("Sync", () -> this.actions.sync()); sync.setToolTipText("Sync now"); right.add(sync);
        header.add(right, BorderLayout.EAST);
        return Ui.fit(header);
    }
    /** Event | My claims, as one strip of buttons; the open tab is lighter and says so to screen readers. */
    private JPanel tabs()
    {
        JPanel strip = new JPanel(new GridLayout(1, 2, 2, 0)); strip.setOpaque(false);
        String[][] all = {{"event", "Event"}, {"me", "My claims"}};
        for (String[] t : all)
        {
            boolean open = t[0].equals(tab);
            JButton button = new JButton(t[1]); button.setFocusPainted(false); button.setContentAreaFilled(false); button.setOpaque(true);
            button.setFont(open ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
            button.setBackground(open ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR); button.setForeground(open ? Color.WHITE : Ui.MUTED);
            button.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, open ? Ui.GOLD : ColorScheme.DARKER_GRAY_COLOR), BorderFactory.createEmptyBorder(6, 2, 4, 2)));
            button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR)); button.getAccessibleContext().setAccessibleName(t[1] + (open ? ", open" : ""));
            button.addActionListener(e -> { tab = t[0]; render(); getScrollPane().getVerticalScrollBar().setValue(0); });
            strip.add(button);
        }
        return Ui.fit(strip);
    }
    /** For the development preview only: open a tab before drawing. */
    public void showTab(String name) { tab = name; render(); }
    public void render()
    {
        content.removeAll(); content.add(header()); Ui.gap(content, 8);
        // Clan defaults one press away at the top while they aren't fully on (user, 2026-11-27: "a more prominent button").
        if (state.linked && ClanSettingsCard.offered(config, state))
        {
            JPanel offer = Ui.card(); content.add(offer);
            JLabel why = Ui.text("Use the clan's recommended uploads and loot filters. You confirm once.", Ui.CARD_WIDTH); offer.add(why);
            Ui.gap(offer, 4);
            offer.add(Ui.fit(Ui.primary("Use clan defaults", () -> ClanSettingsCard.enable(this, config, ClanSettingsCard.preset(state), actions))));
            Ui.gap(content, 8);
        }
        content.add(tabs()); Ui.gap(content, 6);
        if (!state.linked) { precheckViews.clear(); precheckSchemas.clear(); content.add(new SetupCard(config, state, link, actions)); }
        else if (tab.equals("me")) { renderMine(); }
        else { renderEvent(); }
        statusLabel.setText("<html><body style='width:" + Ui.css(Ui.WIDTH) + "px'>" + Ui.html(status) + "</body></html>"); content.add(statusLabel);
        footer = new StatusFooter(state, unsent, actions::sync); content.add(footer); content.revalidate(); content.repaint(); revalidate(); repaint();
    }
    private void renderMine()
    {
        if (!state.message.isEmpty() && !state.message.equals("Synced")) { content.add(Ui.muted(state.message, Ui.WIDTH)); }
        JPanel claims = Ui.section(content, "claims:any", "My recent claims", null, closed); claims.add(new ClaimsList(Json.array(state.sync(), "claims"), -1, 25));
        Ui.gap(content, 6); content.add(new ClanSettingsCard(config, state, actions));
    }
    private void renderEvent()
    {
        if (!state.message.isEmpty() && !state.message.equals("Synced")) { content.add(Ui.muted(state.message, Ui.WIDTH)); }
        // A bank answer waiting to be sent goes first (user, 2026-11-27: it "showed at the bottom, not near the top").
        renderBank(); content.add(bankContent);
        JsonArray events = state.events();
        if (events.size() == 0)
        {
            JPanel empty = Ui.card(); content.add(empty);
            empty.add(Ui.bold("No events right now", Ui.CARD_WIDTH));
            empty.add(Ui.muted("You are not on the roster of a live or upcoming event. Sign up on the site, then sync.", Ui.CARD_WIDTH));
            Ui.gap(empty, 4); Ui.link(empty, "Clan events", "https://ironcladrs.com/events");
        }
        else
        {
            java.util.List<JsonObject> choices = new ArrayList<>();
            for (JsonElement value : events) { if (value.isJsonObject() && choices.size() < 30) { choices.add(value.getAsJsonObject()); } }
            JsonObject chosen = choices.stream().filter(event -> Json.number(event, "id", -1) == selected).findFirst().orElse(choices.isEmpty() ? new JsonObject() : choices.get(0));
            selected = Json.number(chosen, "id", -1);
            if (choices.size() > 1)
            {
                JComboBox<String> select = new JComboBox<>(choices.stream().map(event -> Ui.plain(Json.text(event, "name"))).toArray(String[]::new));
                select.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28)); select.setAlignmentX(Component.LEFT_ALIGNMENT); select.setSelectedIndex(choices.indexOf(chosen));
                select.setToolTipText("Your events (" + choices.size() + ")"); select.getAccessibleContext().setAccessibleName("Choose an event");
                select.addActionListener(event -> { selected = Json.number(choices.get(select.getSelectedIndex()), "id", -1); render(); }); content.add(select); Ui.gap(content, 6);
            }
            JsonArray owed = Json.array(chosen, "prechecksOwed");
            if (!owed.equals(precheckSchemas.get(selected)))
            { precheckSchemas.put(selected, owed.deepCopy()); precheckViews.put(selected, new PrecheckList(selected, owed, actions, state.feature("prechecks"), state.feature("bankPrechecks"))); }
            content.add(new EventCard(chosen, Json.array(state.sync(), "claims"), items, actions, precheckViews.get(selected), state.feature("captain"), closed));
        }
    }
}

