public class EventViewTest
{
    private JsonObject event(JsonObject view)
    {
        return Json.obj("id", 7, "name", "Future event", "type", "unknown-engine", "typeLabel", "Clan event", "state", "live",
            "startsAt", "2000-01-01T00:00:00Z", "endsAt", "2100-01-01T00:00:00Z", "url", "https://ironcladrs.com/events/7",
            "view", view, "match", Json.obj("mode", "all"), "tasks", new JsonArray());
    }
    @Test public void futureEventTypesUseTheStandardContractWithoutAClientRegistry()
    {
        JsonObject event = event(Json.obj("version", 1, "mode", "standard", "futureField", "ignored"));
        assertTrue(EventView.supported(event)); assertTrue(SessionState.inWindow(event, Instant.now()));
        event.remove("view"); assertTrue(EventView.supported(event));
    }
    @Test public void unknownContractsStayVisibleButCannotRequestAutomaticEventUploads()
    {
        for (JsonObject view : new JsonObject[]{Json.obj("version", 1.5, "mode", "standard"), Json.obj("version", "1", "mode", "standard"), Json.obj("version", 2, "mode", "standard"), Json.obj("version", 1, "mode", "new-layout"), Json.obj("version", 1, "mode", "generic"), new JsonObject()})
        {
            JsonObject event = event(view); JsonArray events = new JsonArray(); events.add(event);
            SessionState state = new SessionState(true, "", Instant.now(), new JsonObject(), Json.obj("events", events));
            assertEquals(1, state.events().size()); assertFalse(state.hasLiveEvent(Instant.now()));
            JsonObject safe = state.events().get(0).getAsJsonObject(); assertEquals("none", Json.text(Json.object(safe, "match"), "mode"));
            assertFalse(LootMatcher.matches(events, -1, "Boss", new JsonArray(), Instant.now()));
            assertEquals(0, Json.array(safe, "prechecksOwed").size());
        }
    }
    @Test public void fallbackRendersAWebsiteHandoffWithoutNeedingEngineComponents() throws Exception
    {
        javax.swing.SwingUtilities.invokeAndWait(() -> {
            EventCard card = new EventCard(event(Json.obj("version", 1, "mode", "generic")), new JsonArray(), null, null, null, false, new java.util.HashSet<>());
            boolean open = false;
            java.util.Deque<java.awt.Component> walk = new java.util.ArrayDeque<>(java.util.Collections.singletonList(card));
            while (!walk.isEmpty())
            {
                java.awt.Component component = walk.pop();
                if (component instanceof javax.swing.AbstractButton)
                {
                    String text = ((javax.swing.AbstractButton) component).getText();
                    assertFalse("No task section in the hand-off view", text.contains("Tasks"));
                    if (text.equals("Open event on site")) { open = true; }
                }
                if (component instanceof javax.swing.JLabel) { assertFalse(((javax.swing.JLabel) component).getText().contains("Tasks")); }
                if (component instanceof java.awt.Container) { walk.addAll(java.util.Arrays.asList(((java.awt.Container) component).getComponents())); }
            }
            assertTrue(open);
            assertTrue(EventView.message(event(Json.obj("version", 99, "mode", "generic"))).contains("paused"));
        });
    }
}

package com.ironcladrs.events;

import com.google.gson.JsonObject;
import com.ironcladrs.events.api.dto.Json;
import com.ironcladrs.events.filters.Filters;
import com.ironcladrs.events.sync.SessionState;
import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.*;

public class FiltersTest
{
    private static SessionState withPreset(JsonObject filters)
    { return new SessionState(true, "", Instant.now(), new JsonObject(), Json.obj("clanPreset", Json.obj("version", 1, "filters", filters))); }

    @Test public void ownSettingsApplyUntilClanFiltersAreOn()
    {
        IroncladEventsConfig own = new IroncladEventsConfig()
        {
            @Override public int levelMinimum() { return 70; }
            @Override public int levelInterval() { return 5; }
            @Override public String alwaysSendItems() { return "Dragon claws, Pet rock"; }
            @Override public String onlyAccounts() { return "Main Name"; }
        };
        SessionState clanSays = withPreset(Json.obj("levelMinimum", 90, "relayBroadcasts", false));
        Filters mine = new Filters(own, clanSays);
        assertFalse(mine.clan);
        assertTrue(mine.announcesLevel(70)); assertTrue(mine.announcesLevel(85)); assertFalse(mine.announcesLevel(86)); assertFalse(mine.announcesLevel(65));
        assertTrue(mine.alwaysSends("dragon claws")); assertFalse(mine.alwaysSends("Bones"));
        assertTrue(mine.accountAllowed("main name")); assertFalse(mine.accountAllowed("My Alt"));

        IroncladEventsConfig following = new IroncladEventsConfig()
        {
            @Override public boolean useClanSettings() { return true; }
            @Override public int levelInterval() { return 5; }
            @Override public String onlyAccounts() { return "Main Name"; }
        };
        Filters clan = new Filters(following, clanSays);
        assertTrue(clan.clan);
        assertEquals("the clan's minimum", 90, clan.levelMinimum);
        assertEquals("a rule the clan left out keeps the member's own", 5, clan.levelInterval);
        assertFalse(clan.relayBroadcasts);
        assertFalse("the account list is always the member's own", clan.accountAllowed("My Alt"));
    }

    @Test public void totalsCluesAndRegionsFollowTheirRules()
    {
        Filters f = new Filters(new IroncladEventsConfig()
        {
            @Override public int totalLevelInterval() { return 25; }
            @Override public ClueTier clueMinTier() { return ClueTier.HARD; }
            @Override public String ignoredDeathRegions() { return "9520, 12345"; }
        }, SessionState.empty(""));
        assertTrue(f.announcesTotal(1499, 1500)); assertTrue(f.announcesTotal(1524, 1525)); assertFalse(f.announcesTotal(1525, 1530));
        assertFalse("nothing below 500 total", f.announcesTotal(470, 475));
        assertEquals(1525, f.totalMilestone(1530));
        assertTrue(f.sharesClue("hard")); assertTrue(f.sharesClue("master")); assertFalse(f.sharesClue("medium"));
        assertTrue(f.ignoresDeathIn(9520)); assertFalse(f.ignoresDeathIn(9521));
        assertTrue(Filters.isClueLoot("Clue Scroll (Elite)")); assertFalse(Filters.isClueLoot("Vorkath"));
    }

    @Test public void outOfRangeClanValuesAreClamped()
    {
        Filters f = new Filters(new IroncladEventsConfig() { @Override public boolean useClanSettings() { return true; } },
            withPreset(Json.obj("levelInterval", 0, "screenshotScale", 5, "totalLevelInterval", 10_000)));
        assertEquals(1, f.levelInterval); assertEquals(25, f.screenshotScale); assertEquals(500, f.totalLevelInterval);
    }
}

package com.ironcladrs.events;

import java.lang.reflect.Method;
import java.util.*;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.*;

public class IroncladEventsConfigTest
{
    private final IroncladEventsConfig config = new IroncladEventsConfig() {};

    @Test
    public void connectAndEveryUploadStartOff()
    {
        // Plugin Hub rule: anything that sends to a third-party server starts off (user, 2026-11-27, chose
        // this over "everything starts on"; "Use clan defaults" turns them on in one press after linking).
        assertFalse(config.useClanSettings());
        assertFalse(config.connect());
        for (String key : IroncladEventsConfig.UPLOAD_KEYS) { assertFalse(key, IroncladEventsConfig.upload(config, key)); }
        assertEquals("", config.apiKey());
    }

    /** Connect and every upload carry RuneLite's third-party warning, and every upload key is a real setting. */
    @Test
    public void everySendingSwitchIsWarnedAndEveryUploadKeyExists()
    {
        Set<String> keys = new HashSet<>(), warned = new HashSet<>();
        for (Method method : IroncladEventsConfig.class.getMethods())
        {
            ConfigItem item = method.getAnnotation(ConfigItem.class); if (item == null) { continue; }
            keys.add(item.keyName()); if (!item.warning().isEmpty()) { warned.add(item.keyName()); }
            assertTrue(item.keyName() + " name fits RuneLite's width", item.name().length() <= 25);
        }
        Set<String> sending = new HashSet<>(Arrays.asList(IroncladEventsConfig.UPLOAD_KEYS)); sending.add("connect");
        assertEquals(sending, warned);
        assertEquals(IroncladEventsConfig.UPLOAD_KEYS.length, IroncladEventsConfig.UPLOAD_LABELS.length);
        for (String key : IroncladEventsConfig.UPLOAD_KEYS) { assertTrue(key, keys.contains(key)); }
    }

    @Test
    public void uploadReadsEachSwitchAndUnknownKeysAreOff()
    {
        for (String on : IroncladEventsConfig.UPLOAD_KEYS)
        {
            IroncladEventsConfig one = (IroncladEventsConfig) java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{IroncladEventsConfig.class},
                (proxy, method, args) -> method.getReturnType() == boolean.class ? on.equals(method.getAnnotation(ConfigItem.class) == null ? "" : method.getAnnotation(ConfigItem.class).keyName())
                    : method.getReturnType() == int.class ? 0 : "");
            for (String key : IroncladEventsConfig.UPLOAD_KEYS) { assertEquals(on + "/" + key, on.equals(key), IroncladEventsConfig.upload(one, key)); }
        }
        assertFalse(IroncladEventsConfig.upload(config, "apiKey"));
    }
}

